#!/usr/bin/env python3
"""statix - Lints and suggestions for the Nix programming language."""

import sys
import os
import re
import argparse
from dataclasses import dataclass, field
from typing import Optional, List, Tuple, Union, Any, Dict
from enum import Enum, auto
import fnmatch
import glob

# ============================================================
# Token types
# ============================================================

class TT(Enum):
    # Literals
    INT = auto()
    FLOAT = auto()
    STRING = auto()
    MULTILINE_STRING = auto()
    PATH = auto()
    HPATH = auto()  # ~/path
    SPATH = auto()  # <path>
    URI = auto()
    IDENT = auto()
    # Keywords
    IF = auto()
    THEN = auto()
    ELSE = auto()
    LET = auto()
    IN = auto()
    WITH = auto()
    REC = auto()
    INHERIT = auto()
    NULL = auto()
    TRUE = auto()
    FALSE = auto()
    ASSERT = auto()
    OR_KW = auto()  # "or" keyword
    # Operators
    PLUS = auto()
    MINUS = auto()
    STAR = auto()
    SLASH = auto()
    CONCAT = auto()  # ++
    UPDATE = auto()  # //
    EQ = auto()      # ==
    NEQ = auto()     # !=
    LT = auto()      # <
    GT = auto()      # >
    LEQ = auto()     # <=
    GEQ = auto()     # >=
    AND = auto()     # &&
    OR = auto()      # ||
    IMPL = auto()    # ->
    NOT = auto()     # !
    QUESTION = auto()  # ?
    AT = auto()        # @
    COLON = auto()     # :
    SEMICOLON = auto() # ;
    ASSIGN = auto()    # =
    DOT = auto()       # .
    ELLIPSIS = auto()  # ...
    # Delimiters
    LPAREN = auto()    # (
    RPAREN = auto()    # )
    LBRACE = auto()    # {
    RBRACE = auto()    # }
    LBRACKET = auto()  # [
    RBRACKET = auto()  # ]
    # Special
    EOF = auto()
    ERROR = auto()
    INTERPOLATE_START = auto()  # ${
    DOLLAR = auto()  # $ (bare)

KEYWORDS = {
    'if': TT.IF, 'then': TT.THEN, 'else': TT.ELSE,
    'let': TT.LET, 'in': TT.IN, 'with': TT.WITH,
    'rec': TT.REC, 'inherit': TT.INHERIT, 'null': TT.NULL,
    'true': TT.TRUE, 'false': TT.FALSE, 'assert': TT.ASSERT,
    'or': TT.OR_KW,
}

@dataclass
class Token:
    type: TT
    value: str
    start: int  # byte offset in source
    end: int    # byte offset in source (exclusive)

    @property
    def span(self):
        return (self.start, self.end)

# ============================================================
# Lexer
# ============================================================

class LexError(Exception):
    def __init__(self, msg, pos):
        super().__init__(msg)
        self.pos = pos

class Lexer:
    def __init__(self, src: str):
        self.src = src
        self.pos = 0
        self.tokens = []
        self._tokenize()

    def _tokenize(self):
        src = self.src
        pos = 0
        n = len(src)
        tokens = self.tokens

        while pos < n:
            c = src[pos]

            # Whitespace
            if c in ' \t\n\r':
                pos += 1
                continue

            # Line comment
            if c == '#':
                while pos < n and src[pos] != '\n':
                    pos += 1
                continue

            # Block comment
            if c == '/' and pos+1 < n and src[pos+1] == '*':
                start = pos
                pos += 2
                while pos < n:
                    if src[pos] == '*' and pos+1 < n and src[pos+1] == '/':
                        pos += 2
                        break
                    pos += 1
                continue

            start = pos

            # Numbers
            if c.isdigit():
                # Check for float
                pos += 1
                while pos < n and src[pos].isdigit():
                    pos += 1
                if pos < n and src[pos] == '.' and (pos+1 >= n or src[pos+1] != '.'):
                    pos += 1
                    while pos < n and src[pos].isdigit():
                        pos += 1
                    # scientific notation
                    if pos < n and src[pos] in 'eE':
                        pos += 1
                        if pos < n and src[pos] in '+-':
                            pos += 1
                        while pos < n and src[pos].isdigit():
                            pos += 1
                    tokens.append(Token(TT.FLOAT, src[start:pos], start, pos))
                else:
                    tokens.append(Token(TT.INT, src[start:pos], start, pos))
                continue

            # String interpolation start - need to handle ${
            # but we handle that inside string parsing

            # Identifiers and keywords
            if c.isalpha() or c == '_':
                pos += 1
                while pos < n and (src[pos].isalnum() or src[pos] in '_\'-'):
                    pos += 1
                word = src[start:pos]
                tt = KEYWORDS.get(word, TT.IDENT)
                tokens.append(Token(tt, word, start, pos))
                continue

            # Strings
            if c == '"':
                pos, tok = self._lex_string(src, pos)
                tokens.append(tok)
                continue

            # Multiline strings
            if c == "'" and pos+1 < n and src[pos+1] == "'":
                pos, tok = self._lex_multiline_string(src, pos)
                tokens.append(tok)
                continue

            # Paths
            if c == '.' and pos+1 < n and src[pos+1] == '/':
                pos += 1
                while pos < n and not src[pos] in ' \t\n\r;,)}\]#"\'':
                    pos += 1
                tokens.append(Token(TT.PATH, src[start:pos], start, pos))
                continue

            if c == '/' and pos+1 < n and src[pos+1].isalpha():
                pos += 1
                while pos < n and src[pos] not in ' \t\n\r;,)}\]#"\'':
                    pos += 1
                tokens.append(Token(TT.PATH, src[start:pos], start, pos))
                continue

            # Home path
            if c == '~' and pos+1 < n and src[pos+1] == '/':
                pos += 2
                while pos < n and src[pos] not in ' \t\n\r;,)}\]#"\'':
                    pos += 1
                tokens.append(Token(TT.HPATH, src[start:pos], start, pos))
                continue

            # Store path <...>
            if c == '<':
                # Check if it's a store path
                j = pos + 1
                valid = False
                while j < n and src[j] not in '\n>':
                    j += 1
                if j < n and src[j] == '>':
                    # Looks like a store path
                    content = src[pos+1:j]
                    if re.match(r'^[a-zA-Z0-9_./+-]+$', content):
                        pos = j + 1
                        tokens.append(Token(TT.SPATH, src[start:pos], start, pos))
                        continue
                tokens.append(Token(TT.LT, '<', pos, pos+1))
                pos += 1
                continue

            # Multi-char operators
            if c == '+':
                if pos+1 < n and src[pos+1] == '+':
                    tokens.append(Token(TT.CONCAT, '++', pos, pos+2))
                    pos += 2
                else:
                    tokens.append(Token(TT.PLUS, '+', pos, pos+1))
                    pos += 1
                continue

            if c == '-':
                if pos+1 < n and src[pos+1] == '>':
                    tokens.append(Token(TT.IMPL, '->', pos, pos+2))
                    pos += 2
                else:
                    tokens.append(Token(TT.MINUS, '-', pos, pos+1))
                    pos += 1
                continue

            if c == '*':
                tokens.append(Token(TT.STAR, '*', pos, pos+1))
                pos += 1
                continue

            if c == '/':
                if pos+1 < n and src[pos+1] == '/':
                    tokens.append(Token(TT.UPDATE, '//', pos, pos+2))
                    pos += 2
                else:
                    tokens.append(Token(TT.SLASH, '/', pos, pos+1))
                    pos += 1
                continue

            if c == '=':
                if pos+1 < n and src[pos+1] == '=':
                    tokens.append(Token(TT.EQ, '==', pos, pos+2))
                    pos += 2
                else:
                    tokens.append(Token(TT.ASSIGN, '=', pos, pos+1))
                    pos += 1
                continue

            if c == '!':
                if pos+1 < n and src[pos+1] == '=':
                    tokens.append(Token(TT.NEQ, '!=', pos, pos+2))
                    pos += 2
                else:
                    tokens.append(Token(TT.NOT, '!', pos, pos+1))
                    pos += 1
                continue

            if c == '<':
                if pos+1 < n and src[pos+1] == '=':
                    tokens.append(Token(TT.LEQ, '<=', pos, pos+2))
                    pos += 2
                else:
                    tokens.append(Token(TT.LT, '<', pos, pos+1))
                    pos += 1
                continue

            if c == '>':
                if pos+1 < n and src[pos+1] == '=':
                    tokens.append(Token(TT.GEQ, '>=', pos, pos+2))
                    pos += 2
                else:
                    tokens.append(Token(TT.GT, '>', pos, pos+1))
                    pos += 1
                continue

            if c == '&':
                if pos+1 < n and src[pos+1] == '&':
                    tokens.append(Token(TT.AND, '&&', pos, pos+2))
                    pos += 2
                else:
                    tokens.append(Token(TT.ERROR, '&', pos, pos+1))
                    pos += 1
                continue

            if c == '|':
                if pos+1 < n and src[pos+1] == '|':
                    tokens.append(Token(TT.OR, '||', pos, pos+2))
                    pos += 2
                else:
                    tokens.append(Token(TT.ERROR, '|', pos, pos+1))
                    pos += 1
                continue

            if c == '.':
                if pos+2 < n and src[pos+1] == '.' and src[pos+2] == '.':
                    tokens.append(Token(TT.ELLIPSIS, '...', pos, pos+3))
                    pos += 3
                else:
                    tokens.append(Token(TT.DOT, '.', pos, pos+1))
                    pos += 1
                continue

            if c == '$':
                if pos+1 < n and src[pos+1] == '{':
                    tokens.append(Token(TT.INTERPOLATE_START, '${', pos, pos+2))
                    pos += 2
                else:
                    tokens.append(Token(TT.DOLLAR, '$', pos, pos+1))
                    pos += 1
                continue

            # Single char tokens
            single = {
                '(': TT.LPAREN, ')': TT.RPAREN,
                '{': TT.LBRACE, '}': TT.RBRACE,
                '[': TT.LBRACKET, ']': TT.RBRACKET,
                ':': TT.COLON, ';': TT.SEMICOLON,
                '?': TT.QUESTION, '@': TT.AT,
            }
            if c in single:
                tokens.append(Token(single[c], c, pos, pos+1))
                pos += 1
                continue

            # URI detection: identifier followed by ':'
            # Actually URIs are like scheme:rest where scheme matches [a-zA-Z][a-zA-Z0-9+.-]*
            # Let me handle this better - URIs come as identifiers that look like "scheme"
            # followed by ":" without a space. Actually they're tokenized specially in rnix.
            # Let me check what format URIs are in

            # Skip unknown characters
            tokens.append(Token(TT.ERROR, c, pos, pos+1))
            pos += 1

        tokens.append(Token(TT.EOF, '', n, n))

    def _lex_string(self, src, pos):
        """Lex a double-quoted string, handling interpolations."""
        start = pos
        pos += 1  # skip opening "
        n = len(src)
        while pos < n:
            c = src[pos]
            if c == '"':
                pos += 1
                return pos, Token(TT.STRING, src[start:pos], start, pos)
            elif c == '\\':
                pos += 2  # skip escape sequence
            elif c == '$' and pos+1 < n and src[pos+1] == '{':
                pos += 2
                # Skip interpolation contents  
                depth = 1
                while pos < n and depth > 0:
                    if src[pos] == '{':
                        depth += 1
                    elif src[pos] == '}':
                        depth -= 1
                    elif src[pos] == '"':
                        pos += 1
                        while pos < n and src[pos] != '"':
                            if src[pos] == '\\':
                                pos += 1
                            pos += 1
                        # skip closing "
                    pos += 1
            else:
                pos += 1
        return pos, Token(TT.STRING, src[start:pos], start, pos)

    def _lex_multiline_string(self, src, pos):
        """Lex an indented (multiline) string ''...''."""
        start = pos
        pos += 2  # skip ''
        n = len(src)
        while pos < n:
            c = src[pos]
            if c == "'" and pos+1 < n and src[pos+1] == "'":
                # Check for '''
                if pos+2 < n and src[pos+2] == "'":
                    pos += 3
                    continue
                pos += 2
                return pos, Token(TT.MULTILINE_STRING, src[start:pos], start, pos)
            elif c == '$' and pos+1 < n and src[pos+1] == '{':
                pos += 2
                depth = 1
                while pos < n and depth > 0:
                    if src[pos] == '{':
                        depth += 1
                    elif src[pos] == '}':
                        depth -= 1
                    pos += 1
            else:
                pos += 1
        return pos, Token(TT.MULTILINE_STRING, src[start:pos], start, pos)

# ============================================================
# AST Node types
# ============================================================

@dataclass
class Node:
    start: int
    end: int

    def span(self):
        return (self.start, self.end)

@dataclass
class IntLit(Node):
    value: str

@dataclass
class FloatLit(Node):
    value: str

