# ============================================================
# Parser
# ============================================================

class ParseError(Exception):
    def __init__(self, msg, pos, end=None):
        super().__init__(msg)
        self.pos = pos
        self.end = end if end is not None else pos

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0
        self.errors = []

    def peek(self, offset=0) -> Token:
        i = self.pos + offset
        if i < len(self.tokens):
            return self.tokens[i]
        return self.tokens[-1]  # EOF

    def cur(self) -> Token:
        return self.peek(0)

    def advance(self) -> Token:
        tok = self.tokens[self.pos]
        if self.pos < len(self.tokens) - 1:
            self.pos += 1
        return tok

    def eat(self, tt: TT) -> Token:
        tok = self.cur()
        if tok.type != tt:
            self.errors.append(ParseError(
                f"Expected {tt.name}, got {tok.type.name} '{tok.value}'",
                tok.start, tok.end
            ))
        else:
            self.advance()
        return tok

    def at(self, tt: TT) -> bool:
        return self.cur().type == tt

    def at_any(self, *tts) -> bool:
        return self.cur().type in tts

    def parse(self) -> Any:
        node = self.parse_expr()
        return node

    def parse_expr(self) -> Any:
        return self.parse_impl()

    def parse_impl(self) -> Any:
        left = self.parse_or()
        if self.at(TT.IMPL):
            op_tok = self.advance()
            right = self.parse_impl()  # right-associative
            return BinOp(left.start, right.end, '->', left, right)
        return left

    def parse_or(self) -> Any:
        left = self.parse_and()
        while self.at(TT.OR):
            self.advance()
            right = self.parse_and()
            left = BinOp(left.start, right.end, '||', left, right)
        return left

    def parse_and(self) -> Any:
        left = self.parse_not()
        while self.at(TT.AND):
            self.advance()
            right = self.parse_not()
            left = BinOp(left.start, right.end, '&&', left, right)
        return left

    def parse_not(self) -> Any:
        if self.at(TT.NOT):
            tok = self.advance()
            expr = self.parse_not()
            return UnaryOp(tok.start, expr.end, '!', expr)
        return self.parse_eq()

    def parse_eq(self) -> Any:
        left = self.parse_cmp()
        if self.at_any(TT.EQ, TT.NEQ):
            op = self.advance()
            right = self.parse_cmp()
            return BinOp(left.start, right.end, op.value, left, right)
        return left

    def parse_cmp(self) -> Any:
        left = self.parse_update()
        if self.at_any(TT.LT, TT.GT, TT.LEQ, TT.GEQ):
            op = self.advance()
            right = self.parse_update()
            return BinOp(left.start, right.end, op.value, left, right)
        return left

    def parse_update(self) -> Any:
        left = self.parse_concat()
        while self.at(TT.UPDATE):
            self.advance()
            right = self.parse_concat()
            left = BinOp(left.start, right.end, '//', left, right)
        return left

    def parse_concat(self) -> Any:
        left = self.parse_add()
        while self.at(TT.CONCAT):
            self.advance()
            right = self.parse_add()
            left = BinOp(left.start, right.end, '++', left, right)
        return left

    def parse_add(self) -> Any:
        left = self.parse_mul()
        while self.at_any(TT.PLUS, TT.MINUS):
            op = self.advance()
            right = self.parse_mul()
            left = BinOp(left.start, right.end, op.value, left, right)
        return left

    def parse_mul(self) -> Any:
        left = self.parse_neg()
        while self.at_any(TT.STAR, TT.SLASH):
            op = self.advance()
            right = self.parse_neg()
            left = BinOp(left.start, right.end, op.value, left, right)
        return left

    def parse_neg(self) -> Any:
        if self.at(TT.MINUS):
            tok = self.advance()
            expr = self.parse_neg()
            return UnaryOp(tok.start, expr.end, '-', expr)
        return self.parse_hasattr()

    def parse_hasattr(self) -> Any:
        left = self.parse_apply()
        while self.at(TT.QUESTION):
            self.advance()
            path = self.parse_attr_path()
            left = HasAttr(left.start, path[-1].end if path else left.end, left, path)
        return left

    def parse_apply(self) -> Any:
        """Parse function application (left-associative)."""
        func = self.parse_select()
        while self.is_expr_start():
            arg = self.parse_select()
            func = Apply(func.start, arg.end, func, arg)
        return func

    def is_expr_start(self) -> bool:
        """Returns True if current token can start an expression (for apply)."""
        t = self.cur().type
        return t in (TT.IDENT, TT.INT, TT.FLOAT, TT.STRING, TT.MULTILINE_STRING,
                     TT.PATH, TT.HPATH, TT.SPATH, TT.URI, TT.NULL, TT.TRUE, TT.FALSE,
                     TT.LPAREN, TT.LBRACE, TT.LBRACKET) or self._is_lambda_or_let_start()

    def _is_lambda_or_let_start(self):
        """Check if current position starts a let/if/with/assert/lambda."""
        t = self.cur().type
        return t in (TT.LET, TT.IF, TT.WITH, TT.ASSERT)

    def parse_select(self) -> Any:
        """Parse attribute selection: expr.attr"""
        expr = self.parse_primary()
        while self.at(TT.DOT):
            self.advance()
            attr = self.parse_select_attr()
            # Check for 'or' default
            if self.at(TT.OR_KW):
                self.advance()
                default = self.parse_select()
                return Select(expr.start, default.end, expr, attr, default)
            expr = Select(expr.start, attr.end if hasattr(attr, 'end') else expr.end, expr, attr)
        return expr

    def parse_select_attr(self) -> Any:
        """Parse an attribute name for selection."""
        if self.at(TT.IDENT) or self.at(TT.OR_KW):
            tok = self.advance()
            return Ident(tok.start, tok.end, tok.value)
        elif self.at(TT.STRING):
            tok = self.advance()
            return StringLit(tok.start, tok.end, [tok.value])
        elif self.at(TT.INTERPOLATE_START):
            return self.parse_primary()
        else:
            tok = self.cur()
            return Ident(tok.start, tok.end, tok.value)

    def parse_primary(self) -> Any:
        tok = self.cur()

        if tok.type == TT.INT:
            self.advance()
            return IntLit(tok.start, tok.end, tok.value)

        if tok.type == TT.FLOAT:
            self.advance()
            return FloatLit(tok.start, tok.end, tok.value)

        if tok.type == TT.TRUE:
            self.advance()
            return Bool(tok.start, tok.end, True)

        if tok.type == TT.FALSE:
            self.advance()
            return Bool(tok.start, tok.end, False)

        if tok.type == TT.NULL:
            self.advance()
            return Null(tok.start, tok.end)

        if tok.type in (TT.STRING, TT.MULTILINE_STRING):
            self.advance()
            return StringLit(tok.start, tok.end, [tok.value])

        if tok.type in (TT.PATH, TT.HPATH, TT.SPATH):
            self.advance()
            return Path(tok.start, tok.end, tok.value)

        if tok.type == TT.URI:
            self.advance()
            return Uri(tok.start, tok.end, tok.value)

        if tok.type == TT.IDENT:
            self.advance()
            return Ident(tok.start, tok.end, tok.value)

        if tok.type == TT.LPAREN:
            start = tok.start
            self.advance()
            expr = self.parse_expr()
            end_tok = self.cur()
            if end_tok.type == TT.RPAREN:
                self.advance()
                end = end_tok.end
            else:
                end = expr.end
                self.errors.append(ParseError("Expected ')'", end_tok.start))
            return Paren(start, end, expr)

        if tok.type == TT.LBRACKET:
            return self.parse_list()

        if tok.type == TT.LBRACE:
            return self.parse_attrset()

        if tok.type == TT.LET:
            return self.parse_let()

        if tok.type == TT.IF:
            return self.parse_if()

        if tok.type == TT.WITH:
            return self.parse_with()

        if tok.type == TT.ASSERT:
            return self.parse_assert()

        if tok.type == TT.MINUS:
            # Unary minus - but it's already handled in parse_neg
            # Here it's a primary, so it's an error or we handle it
            t = self.advance()
            expr = self.parse_primary()
            return UnaryOp(t.start, expr.end, '-', expr)

        # Error: unexpected token
        self.errors.append(ParseError(
            f"Unexpected token '{tok.value}' ({tok.type.name})", tok.start, tok.end
        ))
        # Return a placeholder
        if tok.type != TT.EOF:
            self.advance()
        return Null(tok.start, tok.end)

    def parse_list(self) -> List:
        start_tok = self.advance()  # [
        items = []
        while not self.at_any(TT.RBRACKET, TT.EOF):
            items.append(self.parse_select())
        end_tok = self.cur()
        if end_tok.type == TT.RBRACKET:
            self.advance()
        return List(start_tok.start, end_tok.end, items)

    def parse_attrset(self) -> AttrSet:
        start_tok = self.advance()  # {
        bindings = []
        while not self.at_any(TT.RBRACE, TT.EOF):
            binding = self.parse_binding()
            if binding is not None:
                bindings.append(binding)
        end_tok = self.cur()
        if end_tok.type == TT.RBRACE:
            self.advance()
        return AttrSet(start_tok.start, end_tok.end, False, bindings)

    def parse_binding(self) -> Any:
        """Parse a binding or inherit statement."""
        tok = self.cur()

        if tok.type == TT.INHERIT:
            return self.parse_inherit()

        # Parse key = value;
        if tok.type in (TT.IDENT, TT.STRING, TT.OR_KW) or tok.type == TT.INTERPOLATE_START:
            path = self.parse_attr_path()
            if self.at(TT.ASSIGN):
                self.advance()
                value = self.parse_expr()
                end_tok = self.cur()
                if end_tok.type == TT.SEMICOLON:
                    self.advance()
                    end = end_tok.end
                else:
                    end = value.end
                    self.errors.append(ParseError("Expected ';'", end_tok.start))
                return Binding(path[0].start if path else tok.start, end, path, value)
            elif self.at(TT.COLON):
