        self.errors.append(ParseError(f"Unexpected token in binding: {tok.value}", tok.start))
        if tok.type != TT.EOF:
            self.advance()
        return None

    def parse_inherit(self) -> Inherit:
        tok = self.advance()  # inherit
        start = tok.start

        from_ = None
        if self.at(TT.LPAREN):
            self.advance()
            from_ = self.parse_expr()
            if self.at(TT.RPAREN):
                self.advance()

        attrs = []
        while self.at_any(TT.IDENT, TT.OR_KW):
            t = self.advance()
            attrs.append(Ident(t.start, t.end, t.value))

