        return Let(start, body.end, bindings, body)

    def parse_if(self) -> If:
        tok = self.advance()  # if
        start = tok.start
        cond = self.parse_expr()
        if self.at(TT.THEN):
            self.advance()
        then = self.parse_expr()
        if self.at(TT.ELSE):
            self.advance()
        else_ = self.parse_expr()
        return If(start, else_.end, cond, then, else_)

    def parse_with(self) -> With:
        tok = self.advance()  # with
        start = tok.start
        env = self.parse_expr()
        if self.at(TT.SEMICOLON):
            self.advance()
        body = self.parse_expr()
        return With(start, body.end, env, body)

    def parse_assert(self) -> Assert:
        tok = self.advance()  # assert
        start = tok.start
        cond = self.parse_expr()
        if self.at(TT.SEMICOLON):
            self.advance()
        body = self.parse_expr()
        return Assert(start, body.end, cond, body)

