    AND = auto()     # &&
    OR = auto()      # ||
    IMPL = auto()    # ->
    NOT = auto()     # !
    QUESTION = auto()  # ?
    AT = auto()        # @
    COLON = auto()     # :
    SEMICOLON = auto() # ;
    ASSIGN = auto()    # =
    DOT = auto()       # .
    ELLIPSIS = auto()  # ...
    # Delimiters
    LPAREN = auto()    # (
    RPAREN = auto()    # )
    LBRACE = auto()    # {
    RBRACE = auto()    # }
    LBRACKET = auto()  # [
    RBRACKET = auto()  # ]
    # Special
    EOF = auto()
    ERROR = auto()
    INTERPOLATE_START = auto()  # ${
    DOLLAR = auto()  # $ (bare)

KEYWORDS = {
    'if': TT.IF, 'then': TT.THEN, 'else': TT.ELSE,
    'let': TT.LET, 'in': TT.IN, 'with': TT.WITH,
    'rec': TT.REC, 'inherit': TT.INHERIT, 'null': TT.NULL,
    'true': TT.TRUE, 'false': TT.FALSE, 'assert': TT.ASSERT,
    'or': TT.OR_KW,
}

@dataclass
class Token:
    type: TT
    value: str
    start: int  # byte offset in source
    end: int    # byte offset in source (exclusive)

    @property
    def span(self):
        return (self.start, self.end)

# ============================================================
# Lexer
# ============================================================

class LexError(Exception):
    def __init__(self, msg, pos):
        super().__init__(msg)
        self.pos = pos

class Lexer:
    def __init__(self, src: str):
        self.src = src
        self.pos = 0
        self.tokens = []
        self._tokenize()

    def _tokenize(self):
        src = self.src
        pos = 0
        n = len(src)
        tokens = self.tokens

        while pos < n:
            c = src[pos]

            # Whitespace
            if c in ' \t\n\r':
                pos += 1
                continue

            # Line comment
            if c == '#':
                while pos < n and src[pos] != '\n':
                    pos += 1
                continue

            # Block comment
            if c == '/' and pos+1 < n and src[pos+1] == '*':
                start = pos
                pos += 2
                while pos < n:
                    if src[pos] == '*' and pos+1 < n and src[pos+1] == '/':
                        pos += 2
                        break
                    pos += 1
                continue

            start = pos

            # Numbers
            if c.isdigit():
                # Check for float
                pos += 1
                while pos < n and src[pos].isdigit():
                    pos += 1
                if pos < n and src[pos] == '.' and (pos+1 >= n or src[pos+1] != '.'):
                    pos += 1
                    while pos < n and src[pos].isdigit():
                        pos += 1
                    # scientific notation
                    if pos < n and src[pos] in 'eE':
                        pos += 1
                        if pos < n and src[pos] in '+-':
                            pos += 1
                        while pos < n and src[pos].isdigit():
                            pos += 1
                    tokens.append(Token(TT.FLOAT, src[start:pos], start, pos))
                else:
                    tokens.append(Token(TT.INT, src[start:pos], start, pos))
                continue

            # String interpolation start - need to handle ${
            # but we handle that inside string parsing

            # Identifiers and keywords
            if c.isalpha() or c == '_':
                pos += 1
                while pos < n and (src[pos].isalnum() or src[pos] in '_\'-'):
                    pos += 1
                word = src[start:pos]
                tt = KEYWORDS.get(word, TT.IDENT)
                tokens.append(Token(tt, word, start, pos))
                continue

            # Strings
            if c == '"':
                pos, tok = self._lex_string(src, pos)
                tokens.append(tok)
                continue

            # Multiline strings
            if c == "'" and pos+1 < n and src[pos+1] == "'":
                pos, tok = self._lex_multiline_string(src, pos)
                tokens.append(tok)
                continue

            # Paths
            if c == '.' and pos+1 < n and src[pos+1] == '/':
                pos += 1
                while pos < n and not src[pos] in ' \t\n\r;,)}\]#"\'':
                    pos += 1
                tokens.append(Token(TT.PATH, src[start:pos], start, pos))
                continue

            if c == '/' and pos+1 < n and src[pos+1].isalpha():
                pos += 1
                while pos < n and src[pos] not in ' \t\n\r;,)}\]#"\'':
                    pos += 1
                tokens.append(Token(TT.PATH, src[start:pos], start, pos))
                continue

            # Home path
            if c == '~' and pos+1 < n and src[pos+1] == '/':
                pos += 2
                while pos < n and src[pos] not in ' \t\n\r;,)}\]#"\'':
                    pos += 1
                tokens.append(Token(TT.HPATH, src[start:pos], start, pos))
                continue

            # Store path <...>
            if c == '<':
                # Check if it's a store path
                j = pos + 1
                valid = False
                while j < n and src[j] not in '\n>':
                    j += 1
                if j < n and src[j] == '>':
                    # Looks like a store path
                    content = src[pos+1:j]
                    if re.match(r'^[a-zA-Z0-9_./+-]+$', content):
                        pos = j + 1
                        tokens.append(Token(TT.SPATH, src[start:pos], start, pos))
                        continue
                tokens.append(Token(TT.LT, '<', pos, pos+1))
                pos += 1
                continue

            # Multi-char operators
            if c == '+':
                if pos+1 < n and src[pos+1] == '+':
                    tokens.append(Token(TT.CONCAT, '++', pos, pos+2))
                    pos += 2
                else:
                    tokens.append(Token(TT.PLUS, '+', pos, pos+1))
                    pos += 1
                continue

            if c == '-':
                if pos+1 < n and src[pos+1] == '>':
                    tokens.append(Token(TT.IMPL, '->', pos, pos+2))
                    pos += 2
                else:
                    tokens.append(Token(TT.MINUS, '-', pos, pos+1))
                    pos += 1
                continue

            if c == '*':
                tokens.append(Token(TT.STAR, '*', pos, pos+1))
                pos += 1
                continue

            if c == '/':
                if pos+1 < n and src[pos+1] == '/':
                    tokens.append(Token(TT.UPDATE, '//', pos, pos+2))
                    pos += 2
                else:
                    tokens.append(Token(TT.SLASH, '/', pos, pos+1))
                    pos += 1
                continue

            if c == '=':
                if pos+1 < n and src[pos+1] == '=':
                    tokens.append(Token(TT.EQ, '==', pos, pos+2))
                    pos += 2
                else:
                    tokens.append(Token(TT.ASSIGN, '=', pos, pos+1))
                    pos += 1
                continue

            if c == '!':
                if pos+1 < n and src[pos+1] == '=':
                    tokens.append(Token(TT.NEQ, '!=', pos, pos+2))
                    pos += 2
                else:
                    tokens.append(Token(TT.NOT, '!', pos, pos+1))
                    pos += 1
                continue

            if c == '<':
                if pos+1 < n and src[pos+1] == '=':
                    tokens.append(Token(TT.LEQ, '<=', pos, pos+2))
                    pos += 2
                else:
                    tokens.append(Token(TT.LT, '<', pos, pos+1))
                    pos += 1
                continue

            if c == '>':
                if pos+1 < n and src[pos+1] == '=':
                    tokens.append(Token(TT.GEQ, '>=', pos, pos+2))
                    pos += 2
                else:
                    tokens.append(Token(TT.GT, '>', pos, pos+1))
                    pos += 1
                continue

            if c == '&':
                if pos+1 < n and src[pos+1] == '&':
                    tokens.append(Token(TT.AND, '&&', pos, pos+2))
                    pos += 2
                else:
                    tokens.append(Token(TT.ERROR, '&', pos, pos+1))
                    pos += 1
                continue

            if c == '|':
                if pos+1 < n and src[pos+1] == '|':
                    tokens.append(Token(TT.OR, '||', pos, pos+2))
                    pos += 2
                else:
                    tokens.append(Token(TT.ERROR, '|', pos, pos+1))
                    pos += 1
                continue

            if c == '.':
                if pos+2 < n and src[pos+1] == '.' and src[pos+2] == '.':
                    tokens.append(Token(TT.ELLIPSIS, '...', pos, pos+3))
                    pos += 3
                else:
                    tokens.append(Token(TT.DOT, '.', pos, pos+1))
                    pos += 1
                continue

            if c == '$':
                if pos+1 < n and src[pos+1] == '{':
                    tokens.append(Token(TT.INTERPOLATE_START, '${', pos, pos+2))
                    pos += 2
                else:
                    tokens.append(Token(TT.DOLLAR, '$', pos, pos+1))
                    pos += 1
                continue

            # Single char tokens
            single = {
                '(': TT.LPAREN, ')': TT.RPAREN,
                '{': TT.LBRACE, '}': TT.RBRACE,
                '[': TT.LBRACKET, ']': TT.RBRACKET,
                ':': TT.COLON, ';': TT.SEMICOLON,
                '?': TT.QUESTION, '@': TT.AT,
            }
            if c in single:
                tokens.append(Token(single[c], c, pos, pos+1))
                pos += 1
                continue

            # URI detection: identifier followed by ':'
            # Actually URIs are like scheme:rest where scheme matches [a-zA-Z][a-zA-Z0-9+.-]*
            # Let me handle this better - URIs come as identifiers that look like "scheme"
            # followed by ":" without a space. Actually they're tokenized specially in rnix.
            # Let me check what format URIs are in

            # Skip unknown characters
            tokens.append(Token(TT.ERROR, c, pos, pos+1))
            pos += 1

        tokens.append(Token(TT.EOF, '', n, n))

    def _lex_string(self, src, pos):
        """Lex a double-quoted string, handling interpolations."""
        start = pos
        pos += 1  # skip opening "
        n = len(src)
        while pos < n:
            c = src[pos]
            if c == '"':
                pos += 1
                return pos, Token(TT.STRING, src[start:pos], start, pos)
            elif c == '\\':
                pos += 2  # skip escape sequence
            elif c == '$' and pos+1 < n and src[pos+1] == '{':
                pos += 2
                # Skip interpolation contents  
                depth = 1
                while pos < n and depth > 0:
                    if src[pos] == '{':
                        depth += 1
                    elif src[pos] == '}':
                        depth -= 1
                    elif src[pos] == '"':
                        pos += 1
                        while pos < n and src[pos] != '"':
                            if src[pos] == '\\':
                                pos += 1
                            pos += 1
                        # skip closing "
                    pos += 1
            else:
                pos += 1
        return pos, Token(TT.STRING, src[start:pos], start, pos)

    def _lex_multiline_string(self, src, pos):
        """Lex an indented (multiline) string ''...''."""
        start = pos
        pos += 2  # skip ''
        n = len(src)
        while pos < n:
            c = src[pos]
            if c == "'" and pos+1 < n and src[pos+1] == "'":
                # Check for '''
                if pos+2 < n and src[pos+2] == "'":
                    pos += 3
                    continue
                pos += 2
                return pos, Token(TT.MULTILINE_STRING, src[start:pos], start, pos)
            elif c == '$' and pos+1 < n and src[pos+1] == '{':
                pos += 2
                depth = 1
                while pos < n and depth > 0:
                    if src[pos] == '{':
                        depth += 1
                    elif src[pos] == '}':
                        depth -= 1
                    pos += 1
            else:
                pos += 1
        return pos, Token(TT.MULTILINE_STRING, src[start:pos], start, pos)

# ============================================================
# AST Node types
# ============================================================

@dataclass
class Node:
    start: int
    end: int

    def span(self):
        return (self.start, self.end)

@dataclass
class IntLit(Node):
    value: str

@dataclass
class FloatLit(Node):
    value: str

@dataclass  
class StringLit(Node):
    parts: list  # list of strings and interpolated nodes

@dataclass
class Path(Node):
    value: str

@dataclass
class Uri(Node):
    value: str

@dataclass
class Bool(Node):
    value: bool

@dataclass
class Null(Node):
    pass

@dataclass
class Ident(Node):
    name: str

@dataclass
class Select(Node):
    obj: Any
    attr: Any  # Ident or string
    default: Any = None  # for "a.b or default"

@dataclass
class HasAttr(Node):
    obj: Any
    path: list

@dataclass
class List(Node):
    items: list

@dataclass
class AttrSet(Node):
    rec: bool
    bindings: list

@dataclass
class Lambda(Node):
    arg: Any  # Ident or Pattern
    body: Any

@dataclass
class Apply(Node):
    func: Any
    arg: Any

@dataclass
class If(Node):
    cond: Any
    then: Any
    else_: Any

@dataclass
class With(Node):
    env: Any
    body: Any

@dataclass
class Let(Node):
    bindings: list
    body: Any

@dataclass
class LegacyLet(Node):
    """let { ... } syntax"""
    attrset: Any

@dataclass
class Assert(Node):
    cond: Any
    body: Any

@dataclass
class BinOp(Node):
    op: str
    left: Any
    right: Any

@dataclass
class UnaryOp(Node):
    op: str
    expr: Any

@dataclass
class Paren(Node):
    expr: Any

@dataclass
class Binding(Node):
    path: list  # list of attr names
    value: Any

@dataclass
class Inherit(Node):
    from_: Any  # None or an expression (the source attrset)
    attrs: list  # list of Idents

@dataclass
class Pattern(Node):
    """Function parameter pattern { a, b, ... }"""
    formals: list  # list of Formal
    ellipsis: bool
    bind: Any  # Optional Ident for @ bind

@dataclass
class Formal(Node):
    name: str
    default: Any

@dataclass
class LetLegacy(Node):
    """Legacy let { body = ...; } syntax"""
    bindings: list

# ============================================================
# Parser
# ============================================================

class ParseError(Exception):
    def __init__(self, msg, pos, end=None):
        super().__init__(msg)
        self.pos = pos
        self.end = end if end is not None else pos

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0
        self.errors = []

    def peek(self, offset=0) -> Token:
        i = self.pos + offset
        if i < len(self.tokens):
            return self.tokens[i]
        return self.tokens[-1]  # EOF

    def cur(self) -> Token:
        return self.peek(0)

    def advance(self) -> Token:
        tok = self.tokens[self.pos]
        if self.pos < len(self.tokens) - 1:
            self.pos += 1
        return tok

    def eat(self, tt: TT) -> Token:
        tok = self.cur()
        if tok.type != tt:
            self.errors.append(ParseError(
                f"Expected {tt.name}, got {tok.type.name} '{tok.value}'",
                tok.start, tok.end
            ))
        else:
            self.advance()
        return tok

    def at(self, tt: TT) -> bool:
        return self.cur().type == tt

    def at_any(self, *tts) -> bool:
        return self.cur().type in tts

    def parse(self) -> Any:
        node = self.parse_expr()
        return node

    def parse_expr(self) -> Any:
        return self.parse_impl()

    def parse_impl(self) -> Any:
        left = self.parse_or()
        if self.at(TT.IMPL):
            op_tok = self.advance()
            right = self.parse_impl()  # right-associative
            return BinOp(left.start, right.end, '->', left, right)
        return left

    def parse_or(self) -> Any:
        left = self.parse_and()
        while self.at(TT.OR):
            self.advance()
            right = self.parse_and()
            left = BinOp(left.start, right.end, '||', left, right)
        return left

    def parse_and(self) -> Any:
        left = self.parse_not()
        while self.at(TT.AND):
            self.advance()
            right = self.parse_not()
            left = BinOp(left.start, right.end, '&&', left, right)
        return left

    def parse_not(self) -> Any:
        if self.at(TT.NOT):
            tok = self.advance()
            expr = self.parse_not()
            return UnaryOp(tok.start, expr.end, '!', expr)
        return self.parse_eq()

    def parse_eq(self) -> Any:
        left = self.parse_cmp()
        if self.at_any(TT.EQ, TT.NEQ):
            op = self.advance()
            right = self.parse_cmp()
            return BinOp(left.start, right.end, op.value, left, right)
        return left

    def parse_cmp(self) -> Any:
        left = self.parse_update()
        if self.at_any(TT.LT, TT.GT, TT.LEQ, TT.GEQ):
            op = self.advance()
            right = self.parse_update()
            return BinOp(left.start, right.end, op.value, left, right)
        return left

    def parse_update(self) -> Any:
        left = self.parse_concat()
        while self.at(TT.UPDATE):
            self.advance()
            right = self.parse_concat()
            left = BinOp(left.start, right.end, '//', left, right)
        return left

    def parse_concat(self) -> Any:
        left = self.parse_add()
        while self.at(TT.CONCAT):
            self.advance()
            right = self.parse_add()
            left = BinOp(left.start, right.end, '++', left, right)
        return left

    def parse_add(self) -> Any:
        left = self.parse_mul()
        while self.at_any(TT.PLUS, TT.MINUS):
            op = self.advance()
            right = self.parse_mul()
            left = BinOp(left.start, right.end, op.value, left, right)
        return left

    def parse_mul(self) -> Any:
        left = self.parse_neg()
        while self.at_any(TT.STAR, TT.SLASH):
            op = self.advance()
            right = self.parse_neg()
            left = BinOp(left.start, right.end, op.value, left, right)
        return left

    def parse_neg(self) -> Any:
        if self.at(TT.MINUS):
            tok = self.advance()
            expr = self.parse_neg()
            return UnaryOp(tok.start, expr.end, '-', expr)
        return self.parse_hasattr()

    def parse_hasattr(self) -> Any:
        left = self.parse_apply()
        while self.at(TT.QUESTION):
            self.advance()
            path = self.parse_attr_path()
            left = HasAttr(left.start, path[-1].end if path else left.end, left, path)
        return left

    def parse_apply(self) -> Any:
        """Parse function application (left-associative)."""
        func = self.parse_select()
        while self.is_expr_start():
            arg = self.parse_select()
            func = Apply(func.start, arg.end, func, arg)
        return func

    def is_expr_start(self) -> bool:
        """Returns True if current token can start an expression (for apply)."""
        t = self.cur().type
        return t in (TT.IDENT, TT.INT, TT.FLOAT, TT.STRING, TT.MULTILINE_STRING,
                     TT.PATH, TT.HPATH, TT.SPATH, TT.URI, TT.NULL, TT.TRUE, TT.FALSE,
                     TT.LPAREN, TT.LBRACE, TT.LBRACKET) or self._is_lambda_or_let_start()

    def _is_lambda_or_let_start(self):
        """Check if current position starts a let/if/with/assert/lambda."""
        t = self.cur().type
        return t in (TT.LET, TT.IF, TT.WITH, TT.ASSERT)

    def parse_select(self) -> Any:
        """Parse attribute selection: expr.attr"""
        expr = self.parse_primary()
        while self.at(TT.DOT):
            self.advance()
            attr = self.parse_select_attr()
            # Check for 'or' default
            if self.at(TT.OR_KW):
                self.advance()
                default = self.parse_select()
                return Select(expr.start, default.end, expr, attr, default)
            expr = Select(expr.start, attr.end if hasattr(attr, 'end') else expr.end, expr, attr)
        return expr

    def parse_select_attr(self) -> Any:
        """Parse an attribute name for selection."""
        if self.at(TT.IDENT) or self.at(TT.OR_KW):
            tok = self.advance()
            return Ident(tok.start, tok.end, tok.value)
        elif self.at(TT.STRING):
            tok = self.advance()
            return StringLit(tok.start, tok.end, [tok.value])
        elif self.at(TT.INTERPOLATE_START):
            return self.parse_primary()
        else:
            tok = self.cur()
            return Ident(tok.start, tok.end, tok.value)

    def parse_primary(self) -> Any:
        tok = self.cur()

        if tok.type == TT.INT:
            self.advance()
            return IntLit(tok.start, tok.end, tok.value)

        if tok.type == TT.FLOAT:
            self.advance()
            return FloatLit(tok.start, tok.end, tok.value)

        if tok.type == TT.TRUE:
            self.advance()
            return Bool(tok.start, tok.end, True)

        if tok.type == TT.FALSE:
            self.advance()
            return Bool(tok.start, tok.end, False)

        if tok.type == TT.NULL:
            self.advance()
            return Null(tok.start, tok.end)

        if tok.type in (TT.STRING, TT.MULTILINE_STRING):
            self.advance()
            return StringLit(tok.start, tok.end, [tok.value])

        if tok.type in (TT.PATH, TT.HPATH, TT.SPATH):
            self.advance()
            return Path(tok.start, tok.end, tok.value)

        if tok.type == TT.URI:
            self.advance()
            return Uri(tok.start, tok.end, tok.value)

        if tok.type == TT.IDENT:
            self.advance()
            return Ident(tok.start, tok.end, tok.value)

        if tok.type == TT.LPAREN:
            start = tok.start
            self.advance()
            expr = self.parse_expr()
            end_tok = self.cur()
            if end_tok.type == TT.RPAREN:
                self.advance()
                end = end_tok.end
            else:
                end = expr.end
                self.errors.append(ParseError("Expected ')'", end_tok.start))
            return Paren(start, end, expr)

        if tok.type == TT.LBRACKET:
            return self.parse_list()

        if tok.type == TT.LBRACE:
            return self.parse_attrset()

        if tok.type == TT.LET:
            return self.parse_let()

        if tok.type == TT.IF:
            return self.parse_if()

        if tok.type == TT.WITH:
            return self.parse_with()

        if tok.type == TT.ASSERT:
            return self.parse_assert()

        if tok.type == TT.MINUS:
            # Unary minus - but it's already handled in parse_neg
            # Here it's a primary, so it's an error or we handle it
            t = self.advance()
            expr = self.parse_primary()
            return UnaryOp(t.start, expr.end, '-', expr)

        # Error: unexpected token
        self.errors.append(ParseError(
            f"Unexpected token '{tok.value}' ({tok.type.name})", tok.start, tok.end
        ))
        # Return a placeholder
        if tok.type != TT.EOF:
            self.advance()
        return Null(tok.start, tok.end)

    def parse_list(self) -> List:
        start_tok = self.advance()  # [
        items = []
        while not self.at_any(TT.RBRACKET, TT.EOF):
            items.append(self.parse_select())
        end_tok = self.cur()
        if end_tok.type == TT.RBRACKET:
            self.advance()
        return List(start_tok.start, end_tok.end, items)

    def parse_attrset(self) -> AttrSet:
        start_tok = self.advance()  # {
        bindings = []
        while not self.at_any(TT.RBRACE, TT.EOF):
            binding = self.parse_binding()
            if binding is not None:
                bindings.append(binding)
        end_tok = self.cur()
        if end_tok.type == TT.RBRACE:
            self.advance()
        return AttrSet(start_tok.start, end_tok.end, False, bindings)

    def parse_binding(self) -> Any:
        """Parse a binding or inherit statement."""
        tok = self.cur()

        if tok.type == TT.INHERIT:
            return self.parse_inherit()

        # Parse key = value;
        if tok.type in (TT.IDENT, TT.STRING, TT.OR_KW) or tok.type == TT.INTERPOLATE_START:
            path = self.parse_attr_path()
            if self.at(TT.ASSIGN):
                self.advance()
                value = self.parse_expr()
                end_tok = self.cur()
                if end_tok.type == TT.SEMICOLON:
                    self.advance()
                    end = end_tok.end
                else:
                    end = value.end
                    self.errors.append(ParseError("Expected ';'", end_tok.start))
                return Binding(path[0].start if path else tok.start, end, path, value)
            elif self.at(TT.COLON):
                # This is actually a lambda with an identifier arg
                # But we shouldn't be here - lambdas are handled at expression level
                pass

        # Error recovery
