        while pos < n:
            c = src[pos]
            if c == '"':
                pos += 1
                return pos, Token(TT.STRING, src[start:pos], start, pos)
            elif c == '\\':
                pos += 2  # skip escape sequence
            elif c == '$' and pos+1 < n and src[pos+1] == '{':
                pos += 2
                # Skip interpolation contents  
                depth = 1
                while pos < n and depth > 0:
                    if src[pos] == '{':
                        depth += 1
                    elif src[pos] == '}':
                        depth -= 1
                    elif src[pos] == '"':
                        pos += 1
                        while pos < n and src[pos] != '"':
                            if src[pos] == '\\':
                                pos += 1
                            pos += 1
                        # skip closing "
                    pos += 1
            else:
                pos += 1
        return pos, Token(TT.STRING, src[start:pos], start, pos)

    def _lex_multiline_string(self, src, pos):
        """Lex an indented (multiline) string ''...''."""
        start = pos
        pos += 2  # skip ''
        n = len(src)
        while pos < n:
            c = src[pos]
            if c == "'" and pos+1 < n and src[pos+1] == "'":
                # Check for '''
                if pos+2 < n and src[pos+2] == "'":
                    pos += 3
                    continue
                pos += 2
                return pos, Token(TT.MULTILINE_STRING, src[start:pos], start, pos)
            elif c == '$' and pos+1 < n and src[pos+1] == '{':
                pos += 2
                depth = 1
                while pos < n and depth > 0:
                    if src[pos] == '{':
                        depth += 1
                    elif src[pos] == '}':
                        depth -= 1
                    pos += 1
            else:
                pos += 1
        return pos, Token(TT.MULTILINE_STRING, src[start:pos], start, pos)

