    def is_expr_start(self) -> bool:
        """Returns True if current token can start an expression (for apply)."""
        t = self.cur().type
        return t in (TT.IDENT, TT.INT, TT.FLOAT, TT.STRING, TT.MULTILINE_STRING,
                     TT.PATH, TT.HPATH, TT.SPATH, TT.URI, TT.NULL, TT.TRUE, TT.FALSE,
                     TT.LPAREN, TT.LBRACE, TT.LBRACKET) or self._is_lambda_or_let_start()

    def _is_lambda_or_let_start(self):
        """Check if current position starts a let/if/with/assert/lambda."""
        t = self.cur().type
        return t in (TT.LET, TT.IF, TT.WITH, TT.ASSERT)

    def parse_select(self) -> Any:
        """Parse attribute selection: expr.attr"""
        expr = self.parse_primary()
        while self.at(TT.DOT):
            self.advance()
            attr = self.parse_select_attr()
            # Check for 'or' default
            if self.at(TT.OR_KW):
                self.advance()
                default = self.parse_select()
                return Select(expr.start, default.end, expr, attr, default)
            expr = Select(expr.start, attr.end if hasattr(attr, 'end') else expr.end, expr, attr)
        return expr

    def parse_select_attr(self) -> Any:
        """Parse an attribute name for selection."""
        if self.at(TT.IDENT) or self.at(TT.OR_KW):
            tok = self.advance()
            return Ident(tok.start, tok.end, tok.value)
        elif self.at(TT.STRING):
            tok = self.advance()
            return StringLit(tok.start, tok.end, [tok.value])
        elif self.at(TT.INTERPOLATE_START):
            return self.parse_primary()
        else:
            tok = self.cur()
            return Ident(tok.start, tok.end, tok.value)

    def parse_primary(self) -> Any:
        tok = self.cur()

        if tok.type == TT.INT:
            self.advance()
            return IntLit(tok.start, tok.end, tok.value)

        if tok.type == TT.FLOAT:
            self.advance()
            return FloatLit(tok.start, tok.end, tok.value)

        if tok.type == TT.TRUE:
            self.advance()
            return Bool(tok.start, tok.end, True)

        if tok.type == TT.FALSE:
            self.advance()
            return Bool(tok.start, tok.end, False)

        if tok.type == TT.NULL:
            self.advance()
            return Null(tok.start, tok.end)

        if tok.type in (TT.STRING, TT.MULTILINE_STRING):
            self.advance()
            return StringLit(tok.start, tok.end, [tok.value])

        if tok.type in (TT.PATH, TT.HPATH, TT.SPATH):
            self.advance()
            return Path(tok.start, tok.end, tok.value)

        if tok.type == TT.URI:
            self.advance()
            return Uri(tok.start, tok.end, tok.value)

        if tok.type == TT.IDENT:
            self.advance()
            return Ident(tok.start, tok.end, tok.value)

        if tok.type == TT.LPAREN:
            start = tok.start
            self.advance()
            expr = self.parse_expr()
            end_tok = self.cur()
            if end_tok.type == TT.RPAREN:
                self.advance()
                end = end_tok.end
            else:
                end = expr.end
                self.errors.append(ParseError("Expected ')'", end_tok.start))
            return Paren(start, end, expr)

        if tok.type == TT.LBRACKET:
            return self.parse_list()

        if tok.type == TT.LBRACE:
            return self.parse_attrset()

        if tok.type == TT.LET:
            return self.parse_let()

        if tok.type == TT.IF:
            return self.parse_if()

        if tok.type == TT.WITH:
            return self.parse_with()

        if tok.type == TT.ASSERT:
            return self.parse_assert()

        if tok.type == TT.MINUS:
            # Unary minus - but it's already handled in parse_neg
            # Here it's a primary, so it's an error or we handle it
            t = self.advance()
            expr = self.parse_primary()
            return UnaryOp(t.start, expr.end, '-', expr)

        # Error: unexpected token
        self.errors.append(ParseError(
            f"Unexpected token '{tok.value}' ({tok.type.name})", tok.start, tok.end
        ))
        # Return a placeholder
        if tok.type != TT.EOF:
            self.advance()
        return Null(tok.start, tok.end)

    def parse_list(self) -> List:
        start_tok = self.advance()  # [
        items = []
        while not self.at_any(TT.RBRACKET, TT.EOF):
            items.append(self.parse_select())
        end_tok = self.cur()
        if end_tok.type == TT.RBRACKET:
            self.advance()
        return List(start_tok.start, end_tok.end, items)

    def parse_attrset(self) -> AttrSet:
        start_tok = self.advance()  # {
        bindings = []
        while not self.at_any(TT.RBRACE, TT.EOF):
            binding = self.parse_binding()
            if binding is not None:
                bindings.append(binding)
        end_tok = self.cur()
        if end_tok.type == TT.RBRACE:
            self.advance()
        return AttrSet(start_tok.start, end_tok.end, False, bindings)

    def parse_binding(self) -> Any:
        """Parse a binding or inherit statement."""
        tok = self.cur()

        if tok.type == TT.INHERIT:
            return self.parse_inherit()

        # Parse key = value;
        if tok.type in (TT.IDENT, TT.STRING, TT.OR_KW) or tok.type == TT.INTERPOLATE_START:
            path = self.parse_attr_path()
            if self.at(TT.ASSIGN):
                self.advance()
                value = self.parse_expr()
                end_tok = self.cur()
                if end_tok.type == TT.SEMICOLON:
                    self.advance()
                    end = end_tok.end
                else:
                    end = value.end
                    self.errors.append(ParseError("Expected ';'", end_tok.start))
                return Binding(path[0].start if path else tok.start, end, path, value)
            elif self.at(TT.COLON):
                # This is actually a lambda with an identifier arg
                # But we shouldn't be here - lambdas are handled at expression level
                pass

        # Error recovery
        self.errors.append(ParseError(f"Unexpected token in binding: {tok.value}", tok.start))
        if tok.type != TT.EOF:
            self.advance()
        return None

    def parse_inherit(self) -> Inherit:
        tok = self.advance()  # inherit
        start = tok.start

        from_ = None
        if self.at(TT.LPAREN):
            self.advance()
            from_ = self.parse_expr()
            if self.at(TT.RPAREN):
                self.advance()

        attrs = []
        while self.at_any(TT.IDENT, TT.OR_KW):
            t = self.advance()
            attrs.append(Ident(t.start, t.end, t.value))

        end_tok = self.cur()
        if end_tok.type == TT.SEMICOLON:
            self.advance()
            end = end_tok.end
        else:
            end = attrs[-1].end if attrs else (from_.end if from_ else tok.end)

        return Inherit(start, end, from_, attrs)

    def parse_attr_path(self) -> list:
        """Parse a dot-separated attribute path."""
        attrs = []
        if self.at_any(TT.IDENT, TT.OR_KW):
            tok = self.advance()
            attrs.append(Ident(tok.start, tok.end, tok.value))
        elif self.at(TT.STRING):
            tok = self.advance()
            attrs.append(StringLit(tok.start, tok.end, [tok.value]))
        elif self.at(TT.INTERPOLATE_START):
            expr = self.parse_primary()
            attrs.append(expr)

        while self.at(TT.DOT):
            self.advance()
            if self.at_any(TT.IDENT, TT.OR_KW):
                tok = self.advance()
                attrs.append(Ident(tok.start, tok.end, tok.value))
            elif self.at(TT.STRING):
                tok = self.advance()
                attrs.append(StringLit(tok.start, tok.end, [tok.value]))
            elif self.at(TT.INTERPOLATE_START):
                expr = self.parse_primary()
                attrs.append(expr)

        return attrs

    def parse_let(self) -> Any:
        tok = self.advance()  # let
        start = tok.start

        # Check for legacy let syntax: let { ... }
        if self.at(TT.LBRACE):
            # Legacy let syntax
            attrset = self.parse_attrset()
            attrset.rec = False  # it's not rec
            return LegacyLet(start, attrset.end, attrset)

        # Regular let...in
        bindings = []
        while not self.at_any(TT.IN, TT.EOF):
            b = self.parse_binding()
            if b is not None:
                bindings.append(b)

        in_tok = self.cur()
        if in_tok.type == TT.IN:
            self.advance()

        body = self.parse_expr()
        return Let(start, body.end, bindings, body)

    def parse_if(self) -> If:
        tok = self.advance()  # if
        start = tok.start
        cond = self.parse_expr()
        if self.at(TT.THEN):
            self.advance()
        then = self.parse_expr()
        if self.at(TT.ELSE):
            self.advance()
        else_ = self.parse_expr()
        return If(start, else_.end, cond, then, else_)

    def parse_with(self) -> With:
        tok = self.advance()  # with
        start = tok.start
        env = self.parse_expr()
        if self.at(TT.SEMICOLON):
            self.advance()
        body = self.parse_expr()
        return With(start, body.end, env, body)

    def parse_assert(self) -> Assert:
        tok = self.advance()  # assert
        start = tok.start
        cond = self.parse_expr()
        if self.at(TT.SEMICOLON):
            self.advance()
        body = self.parse_expr()
        return Assert(start, body.end, cond, body)

