# ============================================================
# ANSI colors
# ============================================================
RESET = "\033[0m"
YELLOW = "\033[33m"
RED = "\033[31m"
CYAN = "\033[36m"
PURPLE = "\033[35m"
GRAY = "\033[38;5;246m"
LIGHT_GRAY = "\033[38;5;249m"

def yellow(s): return f"{YELLOW}{s}{RESET}"
def red(s): return f"{RED}{s}{RESET}"
def cyan(s): return f"{CYAN}{s}{RESET}"
def purple(s): return f"{PURPLE}{s}{RESET}"
def gray(s): return f"{GRAY}{s}{RESET}"
def light_gray(s): return f"{LIGHT_GRAY}{s}{RESET}"

# ============================================================
# Token types
# ============================================================
class TT(Enum):
    INT=auto(); FLOAT=auto(); STRING=auto(); MSTRING=auto()
    PATH=auto(); HPATH=auto(); SPATH=auto(); URI=auto(); IDENT=auto()
    IF=auto(); THEN=auto(); ELSE=auto(); LET=auto(); IN=auto()
    WITH=auto(); REC=auto(); INHERIT=auto(); NULL=auto(); TRUE=auto()
    FALSE=auto(); ASSERT=auto(); OR_KW=auto()
    PLUS=auto(); MINUS=auto(); STAR=auto(); SLASH=auto()
    CONCAT=auto(); UPDATE=auto(); EQ=auto(); NEQ=auto()
    LT=auto(); GT=auto(); LEQ=auto(); GEQ=auto()
    AND=auto(); OR=auto(); IMPL=auto(); NOT=auto()
    QUESTION=auto(); AT=auto(); COLON=auto(); SEMICOLON=auto()
    ASSIGN=auto(); DOT=auto(); ELLIPSIS=auto()
    LPAREN=auto(); RPAREN=auto(); LBRACE=auto(); RBRACE=auto()
    LBRACKET=auto(); RBRACKET=auto()
    EOF=auto(); ERROR=auto()

KEYWORDS = {
    'if':TT.IF,'then':TT.THEN,'else':TT.ELSE,'let':TT.LET,'in':TT.IN,
    'with':TT.WITH,'rec':TT.REC,'inherit':TT.INHERIT,'null':TT.NULL,
    'true':TT.TRUE,'false':TT.FALSE,'assert':TT.ASSERT,'or':TT.OR_KW,
}

class Token:
    __slots__ = ('type','value','start','end')
    def __init__(self, type, value, start, end):
        self.type = type; self.value = value
        self.start = start; self.end = end

# ============================================================
# Lexer
# ============================================================
def lex(src: str) -> List[Token]:
    tokens = []
    pos = 0
    n = len(src)

    while pos < n:
        c = src[pos]
        if c in ' \t\n\r': pos += 1; continue
        if c == '#':
            while pos < n and src[pos] != '\n': pos += 1
            continue
        if c == '/' and pos+1 < n and src[pos+1] == '*':
            pos += 2
            while pos < n:
                if src[pos] == '*' and pos+1 < n and src[pos+1] == '/':
                    pos += 2; break
                pos += 1
            continue

        start = pos

        # Numbers
        if c.isdigit() or (c == '.' and pos+1 < n and src[pos+1].isdigit()):
            is_float = False
            pos += 1
            while pos < n and src[pos].isdigit(): pos += 1
            if pos < n and src[pos] == '.' and pos+1 < n and src[pos+1] != '.':
                is_float = True; pos += 1
                while pos < n and src[pos].isdigit(): pos += 1
            if pos < n and src[pos] in 'eE':
                is_float = True; pos += 1
                if pos < n and src[pos] in '+-': pos += 1
                while pos < n and src[pos].isdigit(): pos += 1
            tokens.append(Token(TT.FLOAT if is_float else TT.INT, src[start:pos], start, pos))
            continue

        # Identifiers/keywords
        if c.isalpha() or c == '_':
            pos += 1
            while pos < n and (src[pos].isalnum() or src[pos] in '_\'-'): pos += 1
            word = src[start:pos]
            tt = KEYWORDS.get(word, TT.IDENT)
            # Check if this is a URI: word followed by : then non-whitespace
            if tt == TT.IDENT and pos < n and src[pos] == ':' and pos+1 < n and src[pos+1] not in ' \t\n\r':
                # URI - consume rest
                pos += 1  # skip :
                while pos < n and src[pos] not in ' \t\n\r;,)}\]"\'`':
                    pos += 1
                tokens.append(Token(TT.URI, src[start:pos], start, pos))
                continue
            tokens.append(Token(tt, word, start, pos))
            continue

        # Double-quoted string
        if c == '"':
            pos += 1
            while pos < n:
                ch = src[pos]
                if ch == '"': pos += 1; break
                elif ch == '\\': pos += 2
                elif ch == '$' and pos+1 < n and src[pos+1] == '{':
                    pos += 2; depth = 1
                    while pos < n and depth > 0:
                        if src[pos] == '{': depth += 1
                        elif src[pos] == '}': depth -= 1
                        elif src[pos] == '"':
                            pos += 1
                            while pos < n and src[pos] != '"':
                                if src[pos] == '\\': pos += 1
                                pos += 1
                        if depth > 0: pos += 1
                        else: pos += 1; break
                else: pos += 1
            tokens.append(Token(TT.STRING, src[start:pos], start, pos))
            continue

        # Multiline string
        if c == "'" and pos+1 < n and src[pos+1] == "'":
            pos += 2
            while pos < n:
                if src[pos] == "'" and pos+1 < n and src[pos+1] == "'":
                    if pos+2 < n and src[pos+2] == "'": pos += 3; continue
                    pos += 2; break
                elif src[pos] == '$' and pos+1 < n and src[pos+1] == '{':
                    pos += 2; depth = 1
                    while pos < n and depth > 0:
                        if src[pos] == '{': depth += 1
                        elif src[pos] == '}': depth -= 1
                        pos += 1
                else: pos += 1
            tokens.append(Token(TT.MSTRING, src[start:pos], start, pos))
            continue

        # Paths
        if c == '/' and pos+1 < n and (src[pos+1].isalpha() or src[pos+1] in '_./'):
            pos += 1
            while pos < n and src[pos] not in ' \t\n\r;,)}\]"\'`#':
                pos += 1
            tokens.append(Token(TT.PATH, src[start:pos], start, pos))
            continue
        if c == '.' and pos+1 < n and src[pos+1] == '/':
            pos += 2
            while pos < n and src[pos] not in ' \t\n\r;,)}\]"\'`#':
                pos += 1
            tokens.append(Token(TT.PATH, src[start:pos], start, pos))
            continue
        if c == '~' and pos+1 < n and src[pos+1] == '/':
            pos += 2
            while pos < n and src[pos] not in ' \t\n\r;,)}\]"\'`#':
                pos += 1
            tokens.append(Token(TT.HPATH, src[start:pos], start, pos))
            continue

        # Multi-char operators
        if c == '+':
            if pos+1 < n and src[pos+1] == '+':
                tokens.append(Token(TT.CONCAT,'++',pos,pos+2)); pos+=2
            else:
                tokens.append(Token(TT.PLUS,'+',pos,pos+1)); pos+=1
            continue
        if c == '-':
            if pos+1 < n and src[pos+1] == '>':
                tokens.append(Token(TT.IMPL,'->',pos,pos+2)); pos+=2
            else:
                tokens.append(Token(TT.MINUS,'-',pos,pos+1)); pos+=1
            continue
        if c == '*': tokens.append(Token(TT.STAR,'*',pos,pos+1)); pos+=1; continue
        if c == '/':
            if pos+1 < n and src[pos+1] == '/':
                tokens.append(Token(TT.UPDATE,'//',pos,pos+2)); pos+=2
            else:
                tokens.append(Token(TT.SLASH,'/',pos,pos+1)); pos+=1
            continue
        if c == '=':
            if pos+1 < n and src[pos+1] == '=':
                tokens.append(Token(TT.EQ,'==',pos,pos+2)); pos+=2
            else:
                tokens.append(Token(TT.ASSIGN,'=',pos,pos+1)); pos+=1
            continue
        if c == '!':
            if pos+1 < n and src[pos+1] == '=':
                tokens.append(Token(TT.NEQ,'!=',pos,pos+2)); pos+=2
            else:
                tokens.append(Token(TT.NOT,'!',pos,pos+1)); pos+=1
            continue
        if c == '<':
            # Could be <path>, <=, or <
            j = pos+1
            path_chars = True
            while j < n and src[j] != '>':
                if src[j] in ' \t\n': path_chars = False; break
                j += 1
            if j < n and src[j] == '>' and path_chars and j > pos+1:
                tokens.append(Token(TT.SPATH, src[pos:j+1], pos, j+1)); pos = j+1
            elif pos+1 < n and src[pos+1] == '=':
                tokens.append(Token(TT.LEQ,'<=',pos,pos+2)); pos+=2
            else:
                tokens.append(Token(TT.LT,'<',pos,pos+1)); pos+=1
            continue
        if c == '>':
            if pos+1 < n and src[pos+1] == '=':
                tokens.append(Token(TT.GEQ,'>=',pos,pos+2)); pos+=2
            else:
                tokens.append(Token(TT.GT,'>',pos,pos+1)); pos+=1
            continue
        if c == '&':
            if pos+1 < n and src[pos+1] == '&':
                tokens.append(Token(TT.AND,'&&',pos,pos+2)); pos+=2
            else:
                tokens.append(Token(TT.ERROR,'&',pos,pos+1)); pos+=1
            continue
        if c == '|':
            if pos+1 < n and src[pos+1] == '|':
                tokens.append(Token(TT.OR,'||',pos,pos+2)); pos+=2
            else:
                tokens.append(Token(TT.ERROR,'|',pos,pos+1)); pos+=1
            continue
        if c == '.':
            if pos+2 < n and src[pos+1] == '.' and src[pos+2] == '.':
                tokens.append(Token(TT.ELLIPSIS,'...',pos,pos+3)); pos+=3
            else:
                tokens.append(Token(TT.DOT,'.',pos,pos+1)); pos+=1
            continue

        single = {'(':TT.LPAREN,')':TT.RPAREN,'{':TT.LBRACE,'}':TT.RBRACE,
                  '[':TT.LBRACKET,']':TT.RBRACKET,':':TT.COLON,';':TT.SEMICOLON,
                  '?':TT.QUESTION,'@':TT.AT}
        if c in single:
            tokens.append(Token(single[c],c,pos,pos+1)); pos+=1; continue

        tokens.append(Token(TT.ERROR, c, pos, pos+1)); pos+=1

    tokens.append(Token(TT.EOF,'',n,n))
    return tokens

