    except ImportError:
        tomllib = None

# ============================================================
# ANSI colors
# ============================================================
RESET = "\033[0m"
YELLOW = "\033[33m"
RED = "\033[31m"
CYAN = "\033[36m"
PURPLE = "\033[35m"
GRAY = "\033[38;5;246m"
LIGHT_GRAY = "\033[38;5;249m"

def yellow(s): return f"{YELLOW}{s}{RESET}"
def red(s): return f"{RED}{s}{RESET}"
def cyan(s): return f"{CYAN}{s}{RESET}"
def purple(s): return f"{PURPLE}{s}{RESET}"
def gray(s): return f"{GRAY}{s}{RESET}"
def light_gray(s): return f"{LIGHT_GRAY}{s}{RESET}"

# ============================================================
# Token types
# ============================================================
class TT(Enum):
    INT=auto(); FLOAT=auto(); STRING=auto(); MSTRING=auto()
    PATH=auto(); HPATH=auto(); SPATH=auto(); URI=auto(); IDENT=auto()
    IF=auto(); THEN=auto(); ELSE=auto(); LET=auto(); IN=auto()
    WITH=auto(); REC=auto(); INHERIT=auto(); NULL=auto(); TRUE=auto()
    FALSE=auto(); ASSERT=auto(); OR_KW=auto()
    PLUS=auto(); MINUS=auto(); STAR=auto(); SLASH=auto()
    CONCAT=auto(); UPDATE=auto(); EQ=auto(); NEQ=auto()
    LT=auto(); GT=auto(); LEQ=auto(); GEQ=auto()
    AND=auto(); OR=auto(); IMPL=auto(); NOT=auto()
    QUESTION=auto(); AT=auto(); COLON=auto(); SEMICOLON=auto()
    ASSIGN=auto(); DOT=auto(); ELLIPSIS=auto()
    LPAREN=auto(); RPAREN=auto(); LBRACE=auto(); RBRACE=auto()
    LBRACKET=auto(); RBRACKET=auto()
    EOF=auto(); ERROR=auto()

KEYWORDS = {
    'if':TT.IF,'then':TT.THEN,'else':TT.ELSE,'let':TT.LET,'in':TT.IN,
    'with':TT.WITH,'rec':TT.REC,'inherit':TT.INHERIT,'null':TT.NULL,
    'true':TT.TRUE,'false':TT.FALSE,'assert':TT.ASSERT,'or':TT.OR_KW,
}

class Token:
    __slots__ = ('type','value','start','end')
    def __init__(self, type, value, start, end):
        self.type = type; self.value = value
        self.start = start; self.end = end

# ============================================================
# Lexer
# ============================================================
def lex(src: str) -> List[Token]:
    tokens = []
    pos = 0
    n = len(src)

    while pos < n:
        c = src[pos]
        if c in ' \t\n\r': pos += 1; continue
        if c == '#':
            while pos < n and src[pos] != '\n': pos += 1
            continue
        if c == '/' and pos+1 < n and src[pos+1] == '*':
            pos += 2
            while pos < n:
                if src[pos] == '*' and pos+1 < n and src[pos+1] == '/':
                    pos += 2; break
                pos += 1
            continue

        start = pos

        # Numbers
        if c.isdigit() or (c == '.' and pos+1 < n and src[pos+1].isdigit()):
            is_float = False
            pos += 1
            while pos < n and src[pos].isdigit(): pos += 1
            if pos < n and src[pos] == '.' and pos+1 < n and src[pos+1] != '.':
                is_float = True; pos += 1
                while pos < n and src[pos].isdigit(): pos += 1
            if pos < n and src[pos] in 'eE':
                is_float = True; pos += 1
                if pos < n and src[pos] in '+-': pos += 1
                while pos < n and src[pos].isdigit(): pos += 1
            tokens.append(Token(TT.FLOAT if is_float else TT.INT, src[start:pos], start, pos))
            continue

        # Identifiers/keywords
        if c.isalpha() or c == '_':
            pos += 1
            while pos < n and (src[pos].isalnum() or src[pos] in '_\'-'): pos += 1
            word = src[start:pos]
            tt = KEYWORDS.get(word, TT.IDENT)
            # Check if this is a URI: word followed by : then non-whitespace
            if tt == TT.IDENT and pos < n and src[pos] == ':' and pos+1 < n and src[pos+1] not in ' \t\n\r':
                # URI - consume rest
                pos += 1  # skip :
                while pos < n and src[pos] not in ' \t\n\r;,)}\]"\'`':
                    pos += 1
                tokens.append(Token(TT.URI, src[start:pos], start, pos))
                continue
            tokens.append(Token(tt, word, start, pos))
            continue

        # Double-quoted string
        if c == '"':
            pos += 1
            while pos < n:
                ch = src[pos]
                if ch == '"': pos += 1; break
                elif ch == '\\': pos += 2
                elif ch == '$' and pos+1 < n and src[pos+1] == '{':
                    pos += 2; depth = 1
                    while pos < n and depth > 0:
                        if src[pos] == '{': depth += 1
                        elif src[pos] == '}': depth -= 1
                        elif src[pos] == '"':
                            pos += 1
                            while pos < n and src[pos] != '"':
                                if src[pos] == '\\': pos += 1
                                pos += 1
                        if depth > 0: pos += 1
                        else: pos += 1; break
                else: pos += 1
            tokens.append(Token(TT.STRING, src[start:pos], start, pos))
            continue

        # Multiline string
        if c == "'" and pos+1 < n and src[pos+1] == "'":
            pos += 2
            while pos < n:
                if src[pos] == "'" and pos+1 < n and src[pos+1] == "'":
                    if pos+2 < n and src[pos+2] == "'": pos += 3; continue
                    pos += 2; break
                elif src[pos] == '$' and pos+1 < n and src[pos+1] == '{':
                    pos += 2; depth = 1
                    while pos < n and depth > 0:
                        if src[pos] == '{': depth += 1
                        elif src[pos] == '}': depth -= 1
                        pos += 1
                else: pos += 1
            tokens.append(Token(TT.MSTRING, src[start:pos], start, pos))
            continue

        # Paths
        if c == '/' and pos+1 < n and (src[pos+1].isalpha() or src[pos+1] in '_./'):
            pos += 1
            while pos < n and src[pos] not in ' \t\n\r;,)}\]"\'`#':
                pos += 1
            tokens.append(Token(TT.PATH, src[start:pos], start, pos))
            continue
        if c == '.' and pos+1 < n and src[pos+1] == '/':
            pos += 2
            while pos < n and src[pos] not in ' \t\n\r;,)}\]"\'`#':
                pos += 1
            tokens.append(Token(TT.PATH, src[start:pos], start, pos))
            continue
        if c == '~' and pos+1 < n and src[pos+1] == '/':
            pos += 2
            while pos < n and src[pos] not in ' \t\n\r;,)}\]"\'`#':
                pos += 1
            tokens.append(Token(TT.HPATH, src[start:pos], start, pos))
            continue

        # Multi-char operators
        if c == '+':
            if pos+1 < n and src[pos+1] == '+':
                tokens.append(Token(TT.CONCAT,'++',pos,pos+2)); pos+=2
            else:
                tokens.append(Token(TT.PLUS,'+',pos,pos+1)); pos+=1
            continue
        if c == '-':
            if pos+1 < n and src[pos+1] == '>':
                tokens.append(Token(TT.IMPL,'->',pos,pos+2)); pos+=2
            else:
                tokens.append(Token(TT.MINUS,'-',pos,pos+1)); pos+=1
            continue
        if c == '*': tokens.append(Token(TT.STAR,'*',pos,pos+1)); pos+=1; continue
        if c == '/':
            if pos+1 < n and src[pos+1] == '/':
                tokens.append(Token(TT.UPDATE,'//',pos,pos+2)); pos+=2
            else:
                tokens.append(Token(TT.SLASH,'/',pos,pos+1)); pos+=1
            continue
        if c == '=':
            if pos+1 < n and src[pos+1] == '=':
                tokens.append(Token(TT.EQ,'==',pos,pos+2)); pos+=2
            else:
                tokens.append(Token(TT.ASSIGN,'=',pos,pos+1)); pos+=1
            continue
        if c == '!':
            if pos+1 < n and src[pos+1] == '=':
                tokens.append(Token(TT.NEQ,'!=',pos,pos+2)); pos+=2
            else:
                tokens.append(Token(TT.NOT,'!',pos,pos+1)); pos+=1
            continue
        if c == '<':
            # Could be <path>, <=, or <
            j = pos+1
            path_chars = True
            while j < n and src[j] != '>':
                if src[j] in ' \t\n': path_chars = False; break
                j += 1
            if j < n and src[j] == '>' and path_chars and j > pos+1:
                tokens.append(Token(TT.SPATH, src[pos:j+1], pos, j+1)); pos = j+1
            elif pos+1 < n and src[pos+1] == '=':
                tokens.append(Token(TT.LEQ,'<=',pos,pos+2)); pos+=2
            else:
                tokens.append(Token(TT.LT,'<',pos,pos+1)); pos+=1
            continue
        if c == '>':
            if pos+1 < n and src[pos+1] == '=':
                tokens.append(Token(TT.GEQ,'>=',pos,pos+2)); pos+=2
            else:
                tokens.append(Token(TT.GT,'>',pos,pos+1)); pos+=1
            continue
        if c == '&':
            if pos+1 < n and src[pos+1] == '&':
                tokens.append(Token(TT.AND,'&&',pos,pos+2)); pos+=2
            else:
                tokens.append(Token(TT.ERROR,'&',pos,pos+1)); pos+=1
            continue
        if c == '|':
            if pos+1 < n and src[pos+1] == '|':
                tokens.append(Token(TT.OR,'||',pos,pos+2)); pos+=2
            else:
                tokens.append(Token(TT.ERROR,'|',pos,pos+1)); pos+=1
            continue
        if c == '.':
            if pos+2 < n and src[pos+1] == '.' and src[pos+2] == '.':
                tokens.append(Token(TT.ELLIPSIS,'...',pos,pos+3)); pos+=3
            else:
                tokens.append(Token(TT.DOT,'.',pos,pos+1)); pos+=1
            continue

        single = {'(':TT.LPAREN,')':TT.RPAREN,'{':TT.LBRACE,'}':TT.RBRACE,
                  '[':TT.LBRACKET,']':TT.RBRACKET,':':TT.COLON,';':TT.SEMICOLON,
                  '?':TT.QUESTION,'@':TT.AT}
        if c in single:
            tokens.append(Token(single[c],c,pos,pos+1)); pos+=1; continue

        tokens.append(Token(TT.ERROR, c, pos, pos+1)); pos+=1

    tokens.append(Token(TT.EOF,'',n,n))
    return tokens

# ============================================================
# AST Nodes (simple classes with start/end)
# ============================================================
class Node:
    def __init__(self, start, end):
        self.start = start; self.end = end

class IntLit(Node):
    def __init__(self, s, e, v): super().__init__(s,e); self.value=v
class FloatLit(Node):
    def __init__(self, s, e, v): super().__init__(s,e); self.value=v
class StringLit(Node):
    def __init__(self, s, e): super().__init__(s,e)
class Path(Node):
    def __init__(self, s, e, v): super().__init__(s,e); self.value=v
class Uri(Node):
    def __init__(self, s, e, v): super().__init__(s,e); self.value=v
class Bool(Node):
    def __init__(self, s, e, v): super().__init__(s,e); self.value=v
class Null(Node): pass
class Ident(Node):
    def __init__(self, s, e, n): super().__init__(s,e); self.name=n
class Select(Node):
    def __init__(self, s, e, obj, attr, default=None):
        super().__init__(s,e); self.obj=obj; self.attr=attr; self.default=default
class HasAttr(Node):
    def __init__(self, s, e, obj, path):
        super().__init__(s,e); self.obj=obj; self.path=path
class List(Node):
    def __init__(self, s, e, items): super().__init__(s,e); self.items=items
class AttrSet(Node):
    def __init__(self, s, e, rec, bindings):
        super().__init__(s,e); self.rec=rec; self.bindings=bindings
class Lambda(Node):
    def __init__(self, s, e, arg, body):
        super().__init__(s,e); self.arg=arg; self.body=body
class Apply(Node):
    def __init__(self, s, e, func, arg):
        super().__init__(s,e); self.func=func; self.arg=arg
class If(Node):
    def __init__(self, s, e, cond, then, else_):
        super().__init__(s,e); self.cond=cond; self.then=then; self.else_=else_
class With(Node):
    def __init__(self, s, e, env, body):
        super().__init__(s,e); self.env=env; self.body=body
class Let(Node):
    def __init__(self, s, e, bindings, body):
        super().__init__(s,e); self.bindings=bindings; self.body=body
class LegacyLet(Node):
    def __init__(self, s, e, bindings):
        super().__init__(s,e); self.bindings=bindings
class Assert(Node):
    def __init__(self, s, e, cond, body):
        super().__init__(s,e); self.cond=cond; self.body=body
class BinOp(Node):
    def __init__(self, s, e, op, l, r):
        super().__init__(s,e); self.op=op; self.left=l; self.right=r
class UnaryOp(Node):
    def __init__(self, s, e, op, expr):
        super().__init__(s,e); self.op=op; self.expr=expr
class Paren(Node):
    def __init__(self, s, e, expr):
        super().__init__(s,e); self.expr=expr
class Binding(Node):
    def __init__(self, s, e, path, value):
        super().__init__(s,e); self.path=path; self.value=value
class Inherit(Node):
    def __init__(self, s, e, from_, attrs):
        super().__init__(s,e); self.from_=from_; self.attrs=attrs
class Pattern(Node):
    def __init__(self, s, e, formals, ellipsis, bind):
        super().__init__(s,e); self.formals=formals; self.ellipsis=ellipsis; self.bind=bind
class Formal(Node):
    def __init__(self, s, e, name, default):
        super().__init__(s,e); self.name=name; self.default=default

# ============================================================
# Parser
# ============================================================
class ParseError(Exception):
    def __init__(self, msg, pos, end=None):
        super().__init__(msg); self.pos=pos; self.end=end or pos

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens; self.pos = 0; self.errors = []

    def peek(self, off=0):
        i = self.pos + off
        return self.tokens[min(i, len(self.tokens)-1)]

    def cur(self): return self.peek(0)
    def at(self, *tts): return self.cur().type in tts

    def advance(self):
        t = self.tokens[self.pos]
        if self.pos < len(self.tokens)-1: self.pos += 1
        return t

    def eat(self, tt):
        t = self.cur()
        if t.type != tt:
            self.errors.append(ParseError(f"Expected {tt.name}, got {t.type.name}", t.start, t.end))
        else:
            self.advance()
        return t

    def parse(self):
        node = self.parse_expr()
        if not self.at(TT.EOF):
            t = self.cur()
            self.errors.append(ParseError(f"Unexpected token '{t.value}'", t.start, t.end))
        return node

    def parse_expr(self):
        # Check for lambda
        return self.parse_lambda()

    def parse_lambda(self):
        # ident : expr
        # { formals } : expr  
        # ident @ { formals } : expr
        # { formals } @ ident : expr  (also valid)

        saved_pos = self.pos

        if self.at(TT.IDENT):
            # Could be: ident : expr (lambda)
            # or: ident @ { formals } : expr
            if self.peek(1).type == TT.COLON:
                arg_tok = self.advance()
                self.advance()  # :
                body = self.parse_lambda()
                return Lambda(arg_tok.start, body.end, Ident(arg_tok.start, arg_tok.end, arg_tok.value), body)
            elif self.peek(1).type == TT.AT and self.peek(2).type == TT.LBRACE:
                arg_tok = self.advance()
                self.advance()  # @
                pat = self.parse_pattern()
                pat.bind = Ident(arg_tok.start, arg_tok.end, arg_tok.value)
                self.eat(TT.COLON)
                body = self.parse_lambda()
                return Lambda(arg_tok.start, body.end, pat, body)

        if self.at(TT.LBRACE):
            # Could be pattern or attrset
            # Try to detect pattern: look ahead
            if self._is_pattern():
                pat_start = self.cur().start
                pat = self.parse_pattern()
                # Check for @ ident
                if self.at(TT.AT):
                    self.advance()
                    bind_tok = self.cur()
                    self.eat(TT.IDENT)
                    pat.bind = Ident(bind_tok.start, bind_tok.end, bind_tok.value)
                if self.at(TT.COLON):
                    self.advance()
                    body = self.parse_lambda()
                    return Lambda(pat_start, body.end, pat, body)
                else:
                    # Not a lambda, restore and parse as attrset
                    self.pos = saved_pos

        return self.parse_impl()

    def _is_pattern(self):
        """Look ahead to determine if { starts a pattern (not an attrset)."""
        i = self.pos + 1
        toks = self.tokens
        n = len(toks)
        # A pattern looks like: { ident, ... } or { ... } or { }
        # An attrset starts with: ident =, inherit, or string key
        if i >= n: return False
        t = toks[i]
        # Empty {} - could be either, assume attrset unless followed by :
        # { } : is a pattern
        # { } anything else is attrset
        if t.type == TT.RBRACE:
            # Check if : follows
            if i+1 < n and toks[i+1].type == TT.COLON: return True
            return False
        if t.type == TT.ELLIPSIS:
            return True
        if t.type == TT.IDENT:
            # Could be "ident = value" (attrset) or "ident ," or "ident ?" (pattern) or "ident }"
            j = i + 1
            if j < n:
                if toks[j].type in (TT.COMMA if hasattr(TT,'COMMA') else TT.EOF, TT.RBRACE, TT.QUESTION):
                    return True
                if toks[j].type == TT.ASSIGN: return False
                if toks[j].type == TT.ELLIPSIS: return False
                # Need to look further - scan for pattern indicators
                # Simple heuristic: if we see { ident, or { ident ? or { ... } :
                # Let's scan until } and see what follows
        # More complex lookahead: scan for matching } and check what follows
        depth = 1
        j = i
        while j < n and depth > 0:
            if toks[j].type == TT.LBRACE: depth += 1
            elif toks[j].type == TT.RBRACE: depth -= 1
            j += 1
        # j is now past the }
        if j < n and toks[j].type == TT.COLON: return True
        if j < n and toks[j].type == TT.AT: return True
        return False

    def parse_pattern(self):
        """Parse { formals... } pattern."""
        start_tok = self.advance()  # {
        formals = []
        ellipsis = False

        while not self.at(TT.RBRACE, TT.EOF):
            if self.at(TT.ELLIPSIS):
                etok = self.advance()
                ellipsis = True
                # might be followed by }
                break
            if self.at(TT.IDENT):
                name_tok = self.advance()
                default = None
                if self.at(TT.QUESTION):
                    self.advance()
                    default = self.parse_expr()
                formals.append(Formal(name_tok.start, name_tok.end, name_tok.value, default))
            # skip commas
            if self.at(TT.COMMA if hasattr(TT,'COMMA') else TT.EOF):
                self.advance()
            elif not self.at(TT.RBRACE, TT.ELLIPSIS, TT.EOF):
                # comma might be part of IDENT token... 
                # Actually we need a COMMA token. Let me add it.
                break

        end_tok = self.cur()
        if end_tok.type == TT.RBRACE:
            self.advance()

        return Pattern(start_tok.start, end_tok.end, formals, ellipsis, None)

    def parse_impl(self):
        left = self.parse_or()
        if self.at(TT.IMPL):
            self.advance()
            right = self.parse_impl()
            return BinOp(left.start, right.end, '->', left, right)
        return left

    def parse_or(self):
        left = self.parse_and()
        while self.at(TT.OR):
            self.advance()
            right = self.parse_and()
            left = BinOp(left.start, right.end, '||', left, right)
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.at(TT.AND):
            self.advance()
            right = self.parse_not()
            left = BinOp(left.start, right.end, '&&', left, right)
        return left

    def parse_not(self):
        if self.at(TT.NOT):
            tok = self.advance()
            expr = self.parse_not()
            return UnaryOp(tok.start, expr.end, '!', expr)
        return self.parse_eq()

    def parse_eq(self):
        left = self.parse_cmp()
        if self.at(TT.EQ, TT.NEQ):
            op = self.advance()
            right = self.parse_cmp()
            return BinOp(left.start, right.end, op.value, left, right)
        return left

    def parse_cmp(self):
        left = self.parse_update()
        if self.at(TT.LT, TT.GT, TT.LEQ, TT.GEQ):
            op = self.advance()
            right = self.parse_update()
            return BinOp(left.start, right.end, op.value, left, right)
        return left

    def parse_update(self):
        left = self.parse_concat()
        while self.at(TT.UPDATE):
            self.advance()
            right = self.parse_concat()
            left = BinOp(left.start, right.end, '//', left, right)
        return left

    def parse_concat(self):
        left = self.parse_add()
        while self.at(TT.CONCAT):
            self.advance()
            right = self.parse_add()
            left = BinOp(left.start, right.end, '++', left, right)
        return left

    def parse_add(self):
        left = self.parse_mul()
        while self.at(TT.PLUS, TT.MINUS):
            op = self.advance()
            right = self.parse_mul()
            left = BinOp(left.start, right.end, op.value, left, right)
        return left

    def parse_mul(self):
        left = self.parse_neg()
        while self.at(TT.STAR, TT.SLASH):
            op = self.advance()
            right = self.parse_neg()
            left = BinOp(left.start, right.end, op.value, left, right)
        return left

    def parse_neg(self):
        if self.at(TT.MINUS):
            tok = self.advance()
            expr = self.parse_neg()
            return UnaryOp(tok.start, expr.end, '-', expr)
        return self.parse_hasattr()

    def parse_hasattr(self):
        left = self.parse_apply()
        while self.at(TT.QUESTION):
            self.advance()
            path = self.parse_attrpath()
            end = path[-1].end if path else left.end
            left = HasAttr(left.start, end, left, path)
        return left

    def parse_apply(self):
        func = self.parse_select()
        while self._is_expr_start():
            arg = self.parse_select()
            func = Apply(func.start, arg.end, func, arg)
        return func

    def _is_expr_start(self):
        t = self.cur().type
        return t in (TT.IDENT, TT.INT, TT.FLOAT, TT.STRING, TT.MSTRING,
                     TT.PATH, TT.HPATH, TT.SPATH, TT.URI, TT.NULL, TT.TRUE, TT.FALSE,
                     TT.LPAREN, TT.LBRACKET) or (
            t == TT.LBRACE and not self._would_be_lambda()
        )

    def _would_be_lambda(self):
        """Is current { the start of a lambda pattern?"""
        saved = self.pos
        result = self._is_pattern()
        # Don't advance, just peek
        return result

    def parse_select(self):
        expr = self.parse_primary()
        while self.at(TT.DOT):
            self.advance()
            attr = self._parse_select_attr()
            if self.at(TT.OR_KW):
                self.advance()
                default = self.parse_select()
                return Select(expr.start, default.end, expr, attr, default)
            expr = Select(expr.start, attr.end, expr, attr)
        return expr

    def _parse_select_attr(self):
        if self.at(TT.IDENT, TT.OR_KW):
            t = self.advance()
            return Ident(t.start, t.end, t.value)
        elif self.at(TT.STRING):
            t = self.advance()
            return StringLit(t.start, t.end)
        else:
            t = self.cur()
            if not self.at(TT.EOF):
                self.advance()
            return Ident(t.start, t.end, t.value)

    def parse_primary(self):
        t = self.cur()

        if t.type == TT.INT: self.advance(); return IntLit(t.start, t.end, t.value)
        if t.type == TT.FLOAT: self.advance(); return FloatLit(t.start, t.end, t.value)
        if t.type == TT.TRUE: self.advance(); return Bool(t.start, t.end, True)
        if t.type == TT.FALSE: self.advance(); return Bool(t.start, t.end, False)
        if t.type == TT.NULL: self.advance(); return Null(t.start, t.end)
        if t.type in (TT.STRING, TT.MSTRING): self.advance(); return StringLit(t.start, t.end)
        if t.type in (TT.PATH, TT.HPATH, TT.SPATH): self.advance(); return Path(t.start, t.end, t.value)
        if t.type == TT.URI: self.advance(); return Uri(t.start, t.end, t.value)
        if t.type == TT.IDENT: self.advance(); return Ident(t.start, t.end, t.value)

        if t.type == TT.LPAREN:
            start = t.start; self.advance()
            expr = self.parse_expr()
            end_t = self.cur()
            if self.at(TT.RPAREN):
                self.advance(); end = end_t.end
            else:
                end = expr.end
                self.errors.append(ParseError("Expected ')'", end_t.start))
            return Paren(start, end, expr)

        if t.type == TT.LBRACKET:
            start = t.start; self.advance()
            items = []
            while not self.at(TT.RBRACKET, TT.EOF):
                items.append(self.parse_select())  # list items use select-level precedence
            et = self.cur()
            if self.at(TT.RBRACKET): self.advance()
            return List(start, et.end, items)

        if t.type == TT.LBRACE:
            # Attrset or rec attrset (lambda already handled)
            return self.parse_attrset_expr(False)

        if t.type == TT.REC:
            self.advance()
            if self.at(TT.LBRACE):
                return self.parse_attrset_expr(True)
            self.errors.append(ParseError("Expected '{' after 'rec'", t.start))
            return Null(t.start, t.end)

        if t.type == TT.LET: return self.parse_let()
        if t.type == TT.IF: return self.parse_if()
        if t.type == TT.WITH: return self.parse_with()
        if t.type == TT.ASSERT: return self.parse_assert()

        # Error
        self.errors.append(ParseError(f"Unexpected token '{t.value}'", t.start, t.end))
        if not self.at(TT.EOF): self.advance()
        return Null(t.start, t.end)

    def parse_attrset_expr(self, rec):
        start = self.cur().start
        self.advance()  # {
        bindings = []
        while not self.at(TT.RBRACE, TT.EOF):
            b = self.parse_binding()
            if b is not None: bindings.append(b)
        et = self.cur()
        if self.at(TT.RBRACE): self.advance()
        return AttrSet(start, et.end, rec, bindings)

    def parse_binding(self):
        t = self.cur()
        if t.type == TT.INHERIT:
            return self.parse_inherit()
        if t.type in (TT.IDENT, TT.OR_KW, TT.STRING, TT.MSTRING):
            path = self.parse_attrpath()
            if self.at(TT.ASSIGN):
                self.advance()
                value = self.parse_expr()
                et = self.cur()
                end = et.end if self.at(TT.SEMICOLON) else value.end
                if self.at(TT.SEMICOLON): self.advance()
                else: self.errors.append(ParseError("Expected ';'", et.start))
                return Binding(path[0].start if path else t.start, end, path, value)
        # Error recovery
        if not self.at(TT.RBRACE, TT.EOF):
            self.errors.append(ParseError(f"Unexpected token in binding: '{t.value}'", t.start))
            self.advance()
        return None

    def parse_inherit(self):
        tok = self.advance()  # inherit
        from_ = None
        if self.at(TT.LPAREN):
            self.advance()
            from_ = self.parse_expr()
            if self.at(TT.RPAREN): self.advance()
        attrs = []
        while self.at(TT.IDENT, TT.OR_KW):
            at = self.advance()
            attrs.append(Ident(at.start, at.end, at.value))
        et = self.cur()
        end = et.end if self.at(TT.SEMICOLON) else (attrs[-1].end if attrs else tok.end)
        if self.at(TT.SEMICOLON): self.advance()
        return Inherit(tok.start, end, from_, attrs)

    def parse_attrpath(self):
        attrs = []
        def parse_one():
            t = self.cur()
            if t.type in (TT.IDENT, TT.OR_KW):
                self.advance(); return Ident(t.start, t.end, t.value)
            elif t.type in (TT.STRING, TT.MSTRING):
                self.advance(); return StringLit(t.start, t.end)
            else:
                return None
        a = parse_one()
        if a: attrs.append(a)
        while self.at(TT.DOT):
            self.advance()
            a = parse_one()
            if a: attrs.append(a)
        return attrs

    def parse_let(self):
        tok = self.advance()  # let
        start = tok.start
        if self.at(TT.LBRACE):
            # Legacy let { } syntax
            brace_start = self.cur().start
            self.advance()
            bindings = []
            while not self.at(TT.RBRACE, TT.EOF):
                b = self.parse_binding()
                if b is not None: bindings.append(b)
            et = self.cur()
            if self.at(TT.RBRACE): self.advance()
            return LegacyLet(start, et.end, bindings)

        bindings = []
        while not self.at(TT.IN, TT.EOF):
            b = self.parse_binding()
            if b is not None: bindings.append(b)
        if self.at(TT.IN): self.advance()
        body = self.parse_expr()
        return Let(start, body.end, bindings, body)

    def parse_if(self):
        tok = self.advance()
        cond = self.parse_expr()
        if self.at(TT.THEN): self.advance()
        then = self.parse_expr()
        if self.at(TT.ELSE): self.advance()
        else_ = self.parse_expr()
        return If(tok.start, else_.end, cond, then, else_)

    def parse_with(self):
        tok = self.advance()
        env = self.parse_expr()
        if self.at(TT.SEMICOLON): self.advance()
        body = self.parse_expr()
        return With(tok.start, body.end, env, body)

    def parse_assert(self):
        tok = self.advance()
        cond = self.parse_expr()
        if self.at(TT.SEMICOLON): self.advance()
        body = self.parse_expr()
        return Assert(tok.start, body.end, cond, body)

