# ============================================================
# Parser
# ============================================================
class ParseError(Exception):
    def __init__(self, msg, pos, end=None):
        super().__init__(msg); self.pos=pos; self.end=end or pos

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens; self.pos = 0; self.errors = []

    def peek(self, off=0):
        i = self.pos + off
        return self.tokens[min(i, len(self.tokens)-1)]

    def cur(self): return self.peek(0)
    def at(self, *tts): return self.cur().type in tts

    def advance(self):
        t = self.tokens[self.pos]
        if self.pos < len(self.tokens)-1: self.pos += 1
        return t

    def eat(self, tt):
        t = self.cur()
        if t.type != tt:
            self.errors.append(ParseError(f"Expected {tt.name}, got {t.type.name}", t.start, t.end))
        else:
            self.advance()
        return t

    def parse(self):
        node = self.parse_expr()
        if not self.at(TT.EOF):
            t = self.cur()
            self.errors.append(ParseError(f"Unexpected token '{t.value}'", t.start, t.end))
        return node

    def parse_expr(self):
        # Check for lambda
        return self.parse_lambda()

    def parse_lambda(self):
        # ident : expr
        # { formals } : expr  
        # ident @ { formals } : expr
        # { formals } @ ident : expr  (also valid)

        saved_pos = self.pos

        if self.at(TT.IDENT):
            # Could be: ident : expr (lambda)
            # or: ident @ { formals } : expr
            if self.peek(1).type == TT.COLON:
                arg_tok = self.advance()
                self.advance()  # :
                body = self.parse_lambda()
                return Lambda(arg_tok.start, body.end, Ident(arg_tok.start, arg_tok.end, arg_tok.value), body)
            elif self.peek(1).type == TT.AT and self.peek(2).type == TT.LBRACE:
                arg_tok = self.advance()
                self.advance()  # @
                pat = self.parse_pattern()
                pat.bind = Ident(arg_tok.start, arg_tok.end, arg_tok.value)
                self.eat(TT.COLON)
                body = self.parse_lambda()
                return Lambda(arg_tok.start, body.end, pat, body)

        if self.at(TT.LBRACE):
            # Could be pattern or attrset
            # Try to detect pattern: look ahead
            if self._is_pattern():
                pat_start = self.cur().start
                pat = self.parse_pattern()
                # Check for @ ident
                if self.at(TT.AT):
                    self.advance()
                    bind_tok = self.cur()
                    self.eat(TT.IDENT)
                    pat.bind = Ident(bind_tok.start, bind_tok.end, bind_tok.value)
                if self.at(TT.COLON):
                    self.advance()
                    body = self.parse_lambda()
                    return Lambda(pat_start, body.end, pat, body)
                else:
                    # Not a lambda, restore and parse as attrset
                    self.pos = saved_pos

        return self.parse_impl()

    def _is_pattern(self):
        """Look ahead to determine if { starts a pattern (not an attrset)."""
        i = self.pos + 1
        toks = self.tokens
        n = len(toks)
        # A pattern looks like: { ident, ... } or { ... } or { }
        # An attrset starts with: ident =, inherit, or string key
        if i >= n: return False
        t = toks[i]
        # Empty {} - could be either, assume attrset unless followed by :
        # { } : is a pattern
        # { } anything else is attrset
