        if c=='/' and pos+1<n and src[pos+1]=='*':
            pos+=2
            while pos<n:
                if src[pos]=='*' and pos+1<n and src[pos+1]=='/': pos+=2; break
                pos+=1
            continue
        s=pos
        # Numbers
        if c.isdigit():
            pos+=1
            while pos<n and src[pos].isdigit(): pos+=1
            if pos<n and src[pos]=='.' and (pos+1>=n or src[pos+1]!='.') and (pos+1>=n or not src[pos+1].isalpha()):
                pos+=1
                while pos<n and src[pos].isdigit(): pos+=1
                if pos<n and src[pos] in 'eE':
                    pos+=1
                    if pos<n and src[pos] in '+-': pos+=1
                    while pos<n and src[pos].isdigit(): pos+=1
                R.append(Tok(TT.FLOAT,src[s:pos],s,pos))
            else:
                R.append(Tok(TT.INT,src[s:pos],s,pos))
            continue
        # Identifiers / keywords / URIs
        if c.isalpha() or c=='_':
            pos+=1
            while pos<n and (src[pos].isalnum() or src[pos] in '_\'-'): pos+=1
            w=src[s:pos]; tt=KEYWORDS.get(w,TT.IDENT)
            if tt==TT.IDENT and pos<n and src[pos]==':' and pos+1<n and src[pos+1] not in ' \t\n\r({[':
                # URI
                pos+=1
                while pos<n and src[pos] not in ' \t\n\r;,)}\]"\'`#': pos+=1
                R.append(Tok(TT.URI,src[s:pos],s,pos))
            else:
                R.append(Tok(tt,w,s,pos))
            continue
        # Strings
        if c=='"':
            pos+=1
            while pos<n:
                ch=src[pos]
                if ch=='"': pos+=1; break
                elif ch=='\\': pos+=2
                elif ch=='$' and pos+1<n and src[pos+1]=='{':
                    pos+=2; depth=1
                    while pos<n and depth>0:
                        if src[pos]=='{': depth+=1
                        elif src[pos]=='}': depth-=1
                        elif src[pos]=='"' and depth>0:
                            pos+=1
                            while pos<n and src[pos]!='"':
                                if src[pos]=='\\': pos+=1
                                pos+=1
                        if depth>0: pos+=1
                        else: pos+=1; break
                else: pos+=1
            R.append(Tok(TT.STRING,src[s:pos],s,pos)); continue
        # Multiline strings
        if c=="'" and pos+1<n and src[pos+1]=="'":
            pos+=2
            while pos<n:
                if src[pos]=="'" and pos+1<n and src[pos+1]=="'":
                    if pos+2<n and src[pos+2]=="'": pos+=3; continue
                    pos+=2; break
                elif src[pos]=='$' and pos+1<n and src[pos+1]=='{':
                    pos+=2; depth=1
                    while pos<n and depth>0:
                        if src[pos]=='{': depth+=1
                        elif src[pos]=='}': depth-=1
                        pos+=1
                else: pos+=1
            R.append(Tok(TT.MSTRING,src[s:pos],s,pos)); continue
        # Paths
        if (c=='/' and pos+1<n and (src[pos+1].isalpha() or src[pos+1] in '_./')) or \
           (c=='.' and pos+1<n and src[pos+1]=='/'):
            pos+=1
            while pos<n and src[pos] not in ' \t\n\r;,)}\]"\'`#': pos+=1
            R.append(Tok(TT.PATH,src[s:pos],s,pos)); continue
        if c=='~' and pos+1<n and src[pos+1]=='/':
            pos+=2
            while pos<n and src[pos] not in ' \t\n\r;,)}\]"\'`#': pos+=1
            R.append(Tok(TT.HPATH,src[s:pos],s,pos)); continue
        # Store paths <...>
        if c=='<':
            j=pos+1; ok=True
            while j<n and src[j]!='>':
                if src[j] in ' \t\n': ok=False; break
                j+=1
            if ok and j<n and src[j]=='>' and j>pos+1:
                R.append(Tok(TT.SPATH,src[pos:j+1],pos,j+1)); pos=j+1; continue
            elif pos+1<n and src[pos+1]=='=':
                R.append(Tok(TT.LEQ,'<=',pos,pos+2)); pos+=2
            else:
                R.append(Tok(TT.LT,'<',pos,pos+1)); pos+=1
            continue
        # Multi-char operators
        if c=='+':
            if pos+1<n and src[pos+1]=='+': R.append(Tok(TT.CONCAT,'++',pos,pos+2)); pos+=2
            else: R.append(Tok(TT.PLUS,'+',pos,pos+1)); pos+=1; continue
        if c=='-':
            if pos+1<n and src[pos+1]=='>': R.append(Tok(TT.IMPL,'->',pos,pos+2)); pos+=2
            else: R.append(Tok(TT.MINUS,'-',pos,pos+1)); pos+=1; continue
        if c=='*': R.append(Tok(TT.STAR,'*',pos,pos+1)); pos+=1; continue
        if c=='/':
            if pos+1<n and src[pos+1]=='/': R.append(Tok(TT.UPDATE,'//',pos,pos+2)); pos+=2
            else: R.append(Tok(TT.SLASH,'/',pos,pos+1)); pos+=1; continue
        if c=='=':
            if pos+1<n and src[pos+1]=='=': R.append(Tok(TT.EQ,'==',pos,pos+2)); pos+=2
            else: R.append(Tok(TT.ASSIGN,'=',pos,pos+1)); pos+=1; continue
        if c=='!':
            if pos+1<n and src[pos+1]=='=': R.append(Tok(TT.NEQ,'!=',pos,pos+2)); pos+=2
            else: R.append(Tok(TT.NOT,'!',pos,pos+1)); pos+=1; continue
        if c=='>':
            if pos+1<n and src[pos+1]=='=': R.append(Tok(TT.GEQ,'>=',pos,pos+2)); pos+=2
            else: R.append(Tok(TT.GT,'>',pos,pos+1)); pos+=1; continue
        if c=='&':
            if pos+1<n and src[pos+1]=='&': R.append(Tok(TT.AND,'&&',pos,pos+2)); pos+=2
            else: R.append(Tok(TT.ERR,'&',pos,pos+1)); pos+=1; continue
        if c=='|':
            if pos+1<n and src[pos+1]=='|': R.append(Tok(TT.OR,'||',pos,pos+2)); pos+=2
            else: R.append(Tok(TT.ERR,'|',pos,pos+1)); pos+=1; continue
        if c=='.':
            if pos+2<n and src[pos+1]=='.' and src[pos+2]=='...':
                R.append(Tok(TT.ELLIPSIS,'...',pos,pos+3)); pos+=3
            elif pos+2<n and src[pos+1]=='.' and src[pos+2]=='.':
                R.append(Tok(TT.ELLIPSIS,'...',pos,pos+3)); pos+=3
            else: R.append(Tok(TT.DOT,'.',pos,pos+1)); pos+=1; continue
        SM={
            '(':TT.LPAREN,')':TT.RPAREN,'{':TT.LBRACE,'}':TT.RBRACE,
            '[':TT.LBRACKET,']':TT.RBRACKET,':':TT.COLON,';':TT.SEMICOLON,
            '?':TT.QUESTION,'@':TT.AT,',':TT.COMMA
        }
        if c in SM: R.append(Tok(SM[c],c,pos,pos+1)); pos+=1; continue
        R.append(Tok(TT.ERR,c,pos,pos+1)); pos+=1
    R.append(Tok(TT.EOF,'',n,n)); return R

# ─── AST ────────────────────────────────────────────────────────────────────────
class N:
    def __init__(self,s,e): self.start=s; self.end=e

class NInt(N):
    def __init__(self,s,e,v): super().__init__(s,e); self.v=v
class NFloat(N):
    def __init__(self,s,e,v): super().__init__(s,e); self.v=v
class NStr(N): pass
class NPath(N):
    def __init__(self,s,e,v): super().__init__(s,e); self.v=v
class NUri(N):
    def __init__(self,s,e,v): super().__init__(s,e); self.v=v
class NBool(N):
    def __init__(self,s,e,v): super().__init__(s,e); self.v=v
class NNull(N): pass
class NIdent(N):
    def __init__(self,s,e,name): super().__init__(s,e); self.name=name
class NSelect(N):
    def __init__(self,s,e,obj,attr,dflt=None): super().__init__(s,e); self.obj=obj; self.attr=attr; self.dflt=dflt
class NHasAttr(N):
    def __init__(self,s,e,obj,path): super().__init__(s,e); self.obj=obj; self.path=path
class NList(N):
    def __init__(self,s,e,items): super().__init__(s,e); self.items=items
class NAttrSet(N):
    def __init__(self,s,e,rec,bindings): super().__init__(s,e); self.rec=rec; self.bindings=bindings
class NLambda(N):
    def __init__(self,s,e,arg,body): super().__init__(s,e); self.arg=arg; self.body=body
class NApply(N):
    def __init__(self,s,e,f,a): super().__init__(s,e); self.f=f; self.a=a
class NIf(N):
    def __init__(self,s,e,c,t,el): super().__init__(s,e); self.c=c; self.t=t; self.el=el
class NWith(N):
    def __init__(self,s,e,env,body): super().__init__(s,e); self.env=env; self.body=body
class NLet(N):
    def __init__(self,s,e,binds,body): super().__init__(s,e); self.binds=binds; self.body=body
class NLegacyLet(N):
    def __init__(self,s,e,binds): super().__init__(s,e); self.binds=binds
class NAssert(N):
    def __init__(self,s,e,c,body): super().__init__(s,e); self.c=c; self.body=body
class NBinOp(N):
    def __init__(self,s,e,op,l,r): super().__init__(s,e); self.op=op; self.l=l; self.r=r
class NUnary(N):
    def __init__(self,s,e,op,x): super().__init__(s,e); self.op=op; self.x=x
class NParen(N):
    def __init__(self,s,e,x): super().__init__(s,e); self.x=x
class NBinding(N):
    def __init__(self,s,e,path,value): super().__init__(s,e); self.path=path; self.value=value
class NInherit(N):
    def __init__(self,s,e,frm,attrs): super().__init__(s,e); self.frm=frm; self.attrs=attrs
class NPattern(N):
    def __init__(self,s,e,formals,ellipsis,bind): super().__init__(s,e); self.formals=formals; self.ellipsis=ellipsis; self.bind=bind
class NFormal(N):
    def __init__(self,s,e,name,dflt): super().__init__(s,e); self.name=name; self.dflt=dflt

# ─── Parser ─────────────────────────────────────────────────────────────────────
class ParseError(Exception):
    def __init__(self,msg,s,e=None): super().__init__(msg); self.s=s; self.e=e or s

class Parser:
    def __init__(self, toks):
        self.T=toks; self.p=0; self.errs=[]
    def cur(self): return self.T[min(self.p,len(self.T)-1)]
    def peek(self,n=1): return self.T[min(self.p+n,len(self.T)-1)]
    def at(self,*tt): return self.cur().t in tt
    def adv(self):
        t=self.T[self.p]
        if self.p<len(self.T)-1: self.p+=1
        return t
    def eat(self,tt):
        t=self.cur()
        if t.t!=tt:
            self.errs.append(ParseError(f"Expected {tt.name}",t.s,t.e))
        else: self.adv()
        return t

    def parse(self): return self.expr()

    def expr(self): return self.lam()

    def lam(self):
        s=self.p
        # ident : body
        if self.at(TT.IDENT) and self.peek(1).t==TT.COLON:
            t=self.adv(); self.adv()
            body=self.lam()
            return NLambda(t.s,body.end,NIdent(t.s,t.e,t.v),body)
        # ident @ { ... } : body
        if self.at(TT.IDENT) and self.peek(1).t==TT.AT and self.peek(2).t==TT.LBRACE:
            t=self.adv(); self.adv()
            pat=self.pattern()
            pat.bind=NIdent(t.s,t.e,t.v)
            self.eat(TT.COLON)
            body=self.lam()
            return NLambda(t.s,body.end,pat,body)
        # { ... } : body or { ... } @ ident : body
        if self.at(TT.LBRACE) and self._is_pattern():
            s0=self.cur().s
            pat=self.pattern()
            if self.at(TT.AT):
                self.adv()
                bt=self.cur(); self.eat(TT.IDENT)
                pat.bind=NIdent(bt.s,bt.e,bt.v)
            if self.at(TT.COLON):
                self.adv()
                body=self.lam()
                return NLambda(s0,body.end,pat,body)
            else:
                # Not a lambda, restore
                self.p=s
        return self.impl()

    def _is_pattern(self):
        """Check if current { starts a function pattern."""
        i=self.p+1; toks=self.T; n=len(toks)
        # Scan for matching }
        depth=1; j=i
        while j<n and depth>0:
            if toks[j].t==TT.LBRACE: depth+=1
            elif toks[j].t==TT.RBRACE: depth-=1
            j+=1
        # j is past }
        if j<n and toks[j].t in (TT.COLON, TT.AT): return True
        # Also: {} with ... inside
        if i<n and toks[i].t in (TT.ELLIPSIS, TT.RBRACE): return j<n and toks[j].t in (TT.COLON, TT.AT)
        # Check if first element looks like a pattern formal (ident , or ident ? or ident })
        if i<n and toks[i].t==TT.IDENT:
            if i+1<n and toks[i+1].t in (TT.COMMA, TT.QUESTION, TT.RBRACE): return True
            # Could also be ident } followed by :
            return j<n and toks[j].t in (TT.COLON, TT.AT)
        return False

    def pattern(self):
        st=self.adv().s  # {
        formals=[]; ellipsis=False
        while not self.at(TT.RBRACE, TT.EOF):
            if self.at(TT.ELLIPSIS): self.adv(); ellipsis=True; break
            if self.at(TT.IDENT):
                nt=self.adv(); dflt=None
                if self.at(TT.QUESTION): self.adv(); dflt=self.expr()
                formals.append(NFormal(nt.s,nt.e,nt.v,dflt))
            if self.at(TT.COMMA): self.adv()
            elif not self.at(TT.RBRACE, TT.ELLIPSIS, TT.EOF): break
        et=self.cur()
        if self.at(TT.RBRACE): self.adv()
        return NPattern(st,et.e,formals,ellipsis,None)

    def impl(self):
        l=self.orr()
        if self.at(TT.IMPL):
            self.adv(); r=self.impl()
            return NBinOp(l.start,r.end,'->',l,r)
        return l
    def orr(self):
        l=self.andd()
        while self.at(TT.OR):
            self.adv(); r=self.andd()
            l=NBinOp(l.start,r.end,'||',l,r)
        return l
    def andd(self):
        l=self.nott()
        while self.at(TT.AND):
            self.adv(); r=self.nott()
            l=NBinOp(l.start,r.end,'&&',l,r)
        return l
    def nott(self):
        if self.at(TT.NOT):
            t=self.adv(); x=self.nott()
            return NUnary(t.s,x.end,'!',x)
        return self.eq()
    def eq(self):
        l=self.cmp()
        if self.at(TT.EQ,TT.NEQ):
            op=self.adv(); r=self.cmp()
            return NBinOp(l.start,r.end,op.v,l,r)
        return l
    def cmp(self):
        l=self.upd()
        if self.at(TT.LT,TT.GT,TT.LEQ,TT.GEQ):
            op=self.adv(); r=self.upd()
            return NBinOp(l.start,r.end,op.v,l,r)
        return l
    def upd(self):
        l=self.cat()
        while self.at(TT.UPDATE):
            self.adv(); r=self.cat()
            l=NBinOp(l.start,r.end,'//',l,r)
        return l
    def cat(self):
        l=self.add()
        while self.at(TT.CONCAT):
            self.adv(); r=self.add()
            l=NBinOp(l.start,r.end,'++',l,r)
        return l
    def add(self):
        l=self.mul()
        while self.at(TT.PLUS,TT.MINUS):
            op=self.adv(); r=self.mul()
            l=NBinOp(l.start,r.end,op.v,l,r)
        return l
    def mul(self):
        l=self.neg()
        while self.at(TT.STAR,TT.SLASH):
            op=self.adv(); r=self.neg()
            l=NBinOp(l.start,r.end,op.v,l,r)
        return l
    def neg(self):
        if self.at(TT.MINUS):
            t=self.adv(); x=self.neg()
            return NUnary(t.s,x.end,'-',x)
        return self.hasattr()
    def hasattr(self):
        l=self.apply()
        while self.at(TT.QUESTION):
            self.adv(); path=self.attrpath()
            end=path[-1].end if path else l.end
            l=NHasAttr(l.start,end,l,path)
        return l
    def apply(self):
        f=self.select()
        while self._expr_start():
            a=self.select(); f=NApply(f.start,a.end,f,a)
        return f
    def _expr_start(self):
        t=self.cur().t
        if t in (TT.IDENT,TT.INT,TT.FLOAT,TT.STRING,TT.MSTRING,TT.PATH,TT.HPATH,
                 TT.SPATH,TT.URI,TT.NULL,TT.TRUE,TT.FALSE,TT.LPAREN,TT.LBRACKET): return True
        if t==TT.LBRACE: return not self._is_pattern()
        if t==TT.REC: return True
        return False
    def select(self):
        x=self.primary()
        while self.at(TT.DOT):
            self.adv()
            a=self._selattr()
            if self.at(TT.OR_KW):
                self.adv(); d=self.select()
                return NSelect(x.start,d.end,x,a,d)
            x=NSelect(x.start,a.end,x,a)
        return x
    def _selattr(self):
        t=self.cur()
        if t.t in (TT.IDENT,TT.OR_KW): self.adv(); return NIdent(t.s,t.e,t.v)
        elif t.t in (TT.STRING,TT.MSTRING): self.adv(); return NStr(t.s,t.e)
        else:
            if not self.at(TT.EOF): self.adv()
            return NIdent(t.s,t.e,t.v)
    def primary(self):
        t=self.cur()
        if t.t==TT.INT: self.adv(); return NInt(t.s,t.e,t.v)
        if t.t==TT.FLOAT: self.adv(); return NFloat(t.s,t.e,t.v)
        if t.t==TT.TRUE: self.adv(); return NBool(t.s,t.e,True)
        if t.t==TT.FALSE: self.adv(); return NBool(t.s,t.e,False)
        if t.t==TT.NULL: self.adv(); return NNull(t.s,t.e)
        if t.t in (TT.STRING,TT.MSTRING): self.adv(); return NStr(t.s,t.e)
        if t.t in (TT.PATH,TT.HPATH,TT.SPATH): self.adv(); return NPath(t.s,t.e,t.v)
        if t.t==TT.URI: self.adv(); return NUri(t.s,t.e,t.v)
        if t.t==TT.IDENT: self.adv(); return NIdent(t.s,t.e,t.v)
        if t.t==TT.LPAREN:
            s=t.s; self.adv(); x=self.expr(); et=self.cur()
            if self.at(TT.RPAREN): self.adv(); end=et.e
            else: end=x.end; self.errs.append(ParseError("Expected ')'",et.s))
            return NParen(s,end,x)
        if t.t==TT.LBRACKET:
            s=t.s; self.adv(); items=[]
            while not self.at(TT.RBRACKET,TT.EOF): items.append(self.select())
            et=self.cur()
            if self.at(TT.RBRACKET): self.adv()
            return NList(s,et.e,items)
        if t.t==TT.LBRACE: return self.attrset_expr(False)
        if t.t==TT.REC: self.adv(); return self.attrset_expr(True) if self.at(TT.LBRACE) else NNull(t.s,t.e)
        if t.t==TT.LET: return self.let_expr()
        if t.t==TT.IF: return self.if_expr()
        if t.t==TT.WITH: return self.with_expr()
        if t.t==TT.ASSERT: return self.assert_expr()
        self.errs.append(ParseError(f"Unexpected '{t.v}'",t.s,t.e))
        if not self.at(TT.EOF): self.adv()
        return NNull(t.s,t.e)

    def attrset_expr(self,rec):
        s=self.cur().s; self.adv()
        binds=[]; 
        while not self.at(TT.RBRACE,TT.EOF):
            b=self.binding(); 
            if b: binds.append(b)
        et=self.cur()
        if self.at(TT.RBRACE): self.adv()
        return NAttrSet(s,et.e,rec,binds)

    def binding(self):
        t=self.cur()
        if t.t==TT.INHERIT: return self.inherit_()
        if t.t in (TT.IDENT,TT.OR_KW,TT.STRING,TT.MSTRING):
            path=self.attrpath()
            if self.at(TT.ASSIGN):
                self.adv(); val=self.expr()
                et=self.cur(); end=et.e if self.at(TT.SEMICOLON) else val.end
                if self.at(TT.SEMICOLON): self.adv()
                else: self.errs.append(ParseError("Expected ';'",et.s))
                return NBinding(path[0].start if path else t.s,end,path,val)
        if not self.at(TT.RBRACE,TT.EOF):
            self.errs.append(ParseError(f"Unexpected '{t.v}' in binding",t.s))
            self.adv()
        return None

    def inherit_(self):
        t=self.adv(); frm=None
        if self.at(TT.LPAREN):
            self.adv(); frm=self.expr()
            if self.at(TT.RPAREN): self.adv()
        attrs=[]
        while self.at(TT.IDENT,TT.OR_KW):
            at=self.adv(); attrs.append(NIdent(at.s,at.e,at.v))
        et=self.cur(); end=et.e if self.at(TT.SEMICOLON) else (attrs[-1].end if attrs else t.e)
        if self.at(TT.SEMICOLON): self.adv()
        return NInherit(t.s,end,frm,attrs)

    def attrpath(self):
        attrs=[]
        def one():
            t=self.cur()
            if t.t in (TT.IDENT,TT.OR_KW): self.adv(); return NIdent(t.s,t.e,t.v)
            elif t.t in (TT.STRING,TT.MSTRING): self.adv(); return NStr(t.s,t.e)
            return None
        a=one()
        if a: attrs.append(a)
        while self.at(TT.DOT):
            self.adv(); a=one()
            if a: attrs.append(a)
        return attrs

    def let_expr(self):
        t=self.adv(); s=t.s
        if self.at(TT.LBRACE):
            # Legacy let { }
            self.adv(); binds=[]
            while not self.at(TT.RBRACE,TT.EOF):
                b=self.binding()
                if b: binds.append(b)
            et=self.cur()
            if self.at(TT.RBRACE): self.adv()
            return NLegacyLet(s,et.e,binds)
        binds=[]
        while not self.at(TT.IN,TT.EOF):
            b=self.binding()
            if b: binds.append(b)
        if self.at(TT.IN): self.adv()
        body=self.expr()
        return NLet(s,body.end,binds,body)

    def if_expr(self):
        t=self.adv()
        c=self.expr()
        if self.at(TT.THEN): self.adv()
        th=self.expr()
        if self.at(TT.ELSE): self.adv()
        el=self.expr()
        return NIf(t.s,el.end,c,th,el)

    def with_expr(self):
        t=self.adv(); env=self.expr()
        if self.at(TT.SEMICOLON): self.adv()
        body=self.expr()
        return NWith(t.s,body.end,env,body)

    def assert_expr(self):
        t=self.adv(); c=self.expr()
        if self.at(TT.SEMICOLON): self.adv()
        body=self.expr()
        return NAssert(t.s,body.end,c,body)

def parse_nix(src: str):
    toks = lex(src)
    p = Parser(toks)
    tree = p.parse()
    return tree, p.errs

# ─── Position utilities ─────────────────────────────────────────────────────────
def offset_to_linecol(src: str, offset: int) -> Tuple[int,int]:
    """Convert byte offset to (1-based line, 1-based col)."""
    line = 1; col = 1
    for i,c in enumerate(src):
        if i == offset: return (line, col)
        if c == '\n': line += 1; col = 1
        else: col += 1
    return (line, col)

def get_line(src: str, line: int) -> str:
    """Get the content of a 1-based line."""
    lines = src.split('\n')
    if 1 <= line <= len(lines): return lines[line-1]
    return ''

def line_count(src: str) -> int:
    return src.count('\n') + 1

# ─── Diagnostics ────────────────────────────────────────────────────────────────
class Severity(Enum):
    Warning='W'; Error='E'

class Label:
    def __init__(self, start, end, message, primary=True):
        self.start=start; self.end=end; self.message=message; self.primary=primary

class Diag:
    def __init__(self, code, severity, title, labels, notes=None):
        self.code=code; self.severity=severity; self.title=title
        self.labels=labels; self.notes=notes or []

# ─── Rendering ──────────────────────────────────────────────────────────────────
def render_diag(diag: Diag, src: str, filename: str) -> str:
    """Render a diagnostic to colored text."""
    lines = []
    sev = diag.severity
    code = diag.code

    # Header line
    if sev == Severity.Warning:
        header = C(YELLOW, f"[W{code:02d}] Warning:") + f" {diag.title}"
    else:
        header = C(RED, f"[E{code:02d}] Error:") + f" {diag.title}"
    lines.append(header)

    if not diag.labels:
        return '\n'.join(lines)

    # Find the primary label (first one typically)
    primary = diag.labels[0]

    # Determine the line range for all labels
    all_starts = [l.start for l in diag.labels]
    all_ends = [l.end for l in diag.labels]

    # Get line numbers
    start_line, start_col = offset_to_linecol(src, primary.start)

    # Calculate gutter width based on max line number shown
    max_line = max(offset_to_linecol(src, e)[0] for e in all_ends if e <= len(src))
    min_line = min(offset_to_linecol(src, s)[0] for s in all_starts if s <= len(src))
    num_width = len(str(max(max_line, min_line)))
    gutter = num_width + 2  # space + number + space + │... no: " N │" = 4 for single digit
    # Actually: " " + str(lineno).rjust(num_width) + " │" 
    # gutter_display = 1 + num_width + 1 + 1 = num_width + 3
    # But the prefix (for header/annotation lines): " " * (num_width + 2) + "╭" or "·"
    prefix_spaces = num_width + 2  # spaces before ╭/·

    # Header: "   ╭─[file:line:col]"
    loc_line = f"{' ' * prefix_spaces}{C(GRAY,'╭─[')}{filename}:{start_line}:{start_col}{C(GRAY,']')}"
    lines.append(loc_line)

    # Now we need to render all labels
    # Collect unique lines that need to be shown
    label_lines = {}  # line_num -> list of (start_col, end_col, label)
    for lbl in diag.labels:
        ln, sc = offset_to_linecol(src, lbl.start)
        en, ec = offset_to_linecol(src, lbl.end)
        if ln == en:
            # Single-line label
            if ln not in label_lines: label_lines[ln] = []
            label_lines[ln].append((sc, ec, lbl, False, False))
        else:
            # Multi-line label - mark start and end lines
            if ln not in label_lines: label_lines[ln] = []
            label_lines[ln].append((sc, None, lbl, True, False))  # start
            if en not in label_lines: label_lines[en] = []
            label_lines[en].append((None, ec, lbl, False, True))  # end

    # Determine if we have multi-line labels
    has_multiline = any(isinstance(l, Label) and _label_is_multiline(src, l) for l in diag.labels)

    if not has_multiline:
        # Simple single-line rendering
        lines.append(f"{' ' * prefix_spaces}{C(GRAY,'│')}")
        for lbl in diag.labels:
            ln, sc = offset_to_linecol(src, lbl.start)
            en, ec = offset_to_linecol(src, lbl.end)
            src_line = get_line(src, ln)
            # Render the source line
            span_start = lbl.start - _line_start(src, ln)
            span_end = lbl.end - _line_start(src, ln)
            rendered_src = render_source_line(src_line, span_start, span_end)
            num_str = str(ln).rjust(num_width)
            lines.append(f" {C(GRAY, num_str + ' │')} {rendered_src}")
            # Render underline
            underline = render_underline(src_line, span_start, span_end)
            dot_prefix = f" {C(GRAY, ' ' * num_width + ' ·')}"
            lines.append(f"{dot_prefix} {underline}")
            # Render annotation
            annot = render_annotation(src_line, span_start, span_end, lbl.message)
            lines.append(f"{dot_prefix} {annot}")
    else:
        # Multi-line rendering
        lines.extend(render_multiline_labels(src, diag.labels, num_width, prefix_spaces))

    # Closing line
    lines.append(C(GRAY, '─' * (num_width + 2) + '╯'))
    return '\n'.join(lines)

def _label_is_multiline(src, lbl):
    ln, _ = offset_to_linecol(src, lbl.start)
    en, _ = offset_to_linecol(src, lbl.end)
    return ln != en

def _line_start(src, line):
    """Return the byte offset of the start of a 1-based line."""
    pos = 0; ln = 1
    while ln < line:
        i = src.find('\n', pos)
        if i == -1: return len(src)
        pos = i + 1; ln += 1
    return pos

def render_source_line(src_line, span_start, span_end):
    """Render a source line with PURPLE for span, LGRAY for rest."""
    result = []
    for i, c in enumerate(src_line):
        if span_start <= i < span_end:
            result.append(C(PURPLE, c))
        else:
            result.append(C(LGRAY, c))
    return ''.join(result)

def render_underline(src_line, span_start, span_end):
    """Render the ─┬─ underline for a span."""
    if span_start >= span_end:
        return ''
    length = span_end - span_start
    center = length // 2
    result = []
    # Leading spaces (before span)
    result.append(' ' * span_start)
    # The underline
    for i in range(length):
        if i == center:
            result.append(C(PURPLE, '┬'))
        else:
            result.append(C(PURPLE, '─'))
    # Trailing spaces (2 spaces)
    result.append('  ')
    return ''.join(result)

def render_annotation(src_line, span_start, span_end, message):
    """Render the ╰─── annotation line."""
    if span_start >= span_end:
        return ''
    length = span_end - span_start
    center = length // 2
    # Position of ╰ is at span_start + center
    arrow_pos = span_start + center
    # Build the line
    result = []
    result.append(' ' * arrow_pos)
    result.append(C(PURPLE, '╰'))
    # Dashes after ╰ up to at least 1 dash, then space, then message
    dashes = max(1, length - center - 1)
    result.append(C(PURPLE, '─' * dashes))
    result.append(' ')
    result.append(render_message(message))
    return ''.join(result)

def render_message(msg):
    """Render a message with `backtick` items highlighted in CYAN."""
    parts = re.split(r'(`[^`]*`)', msg)
    result = []
    for p in parts:
        if p.startswith('`') and p.endswith('`'):
            result.append(C(CYAN, p[1:-1]))
        else:
            result.append(p)
    return ''.join(result)

def render_multiline_labels(src, labels, num_width, prefix_spaces):
    """Render diagnostics with multi-line spans (like W05, W06)."""
    lines = []
    dot_prefix = f" {C(GRAY, ' ' * num_width + ' ·')}"

    # Separate single-line and multi-line labels
    # For simplicity, handle the common patterns:
    # Pattern 1 (W05): one multi-line span + one annotation
    # Pattern 2 (W06): two multi-line spans
    # Pattern 3 (W20): multiple single-line spans at different lines

    # Check if any label is truly multi-line
    multiline_labels = [l for l in labels if _label_is_multiline(src, l)]
    singleline_labels = [l for l in labels if not _label_is_multiline(src, l)]

    if not multiline_labels and singleline_labels:
        # All single-line but on different lines (W20 style)
        lines.append(f"{' ' * prefix_spaces}{C(GRAY,'│')}")
        for i, lbl in enumerate(singleline_labels):
            ln, sc = offset_to_linecol(src, lbl.start)
            src_line = get_line(src, ln)
            span_s = lbl.start - _line_start(src, ln)
            span_e = lbl.end - _line_start(src, ln)
            rendered_src = render_source_line(src_line, span_s, span_e)
            num_str = str(ln).rjust(num_width)
            lines.append(f" {C(GRAY, num_str + ' │')} {rendered_src}")
            underline = render_underline(src_line, span_s, span_e)
            lines.append(f"{dot_prefix} {underline}")
            annot = render_annotation(src_line, span_s, span_e, lbl.message)
            lines.append(f"{dot_prefix} {annot}")
        return lines

    # For multi-line labels, use the box drawing approach
    # Each multi-line label gets: ╭──▶ on start line, ├──▶ or │ on other lines, ╰─── annotation

    lines.append(f"{' ' * prefix_spaces}{C(GRAY,'│')}")

    # Collect all relevant source lines
    all_line_nums = set()
    for lbl in labels:
        ls, _ = offset_to_linecol(src, lbl.start)
        le, _ = offset_to_linecol(src, lbl.end)
        all_line_nums.add(ls)
        if _label_is_multiline(src, lbl): all_line_nums.add(le)
    all_line_nums = sorted(all_line_nums)

    # Build per-line rendering info
    # For each source line, figure out which labels start/end there
    nml = len(multiline_labels)  # number of multi-line labels

    # For each source line we need to show, determine the label state
    # label_state[i] = 'start' | 'end' | 'middle' for label i

    for ln in all_line_nums:
        src_line = get_line(src, ln)
        num_str = str(ln).rjust(num_width)

        # Determine which multi-line labels start/end at this line
        starting = [i for i,l in enumerate(multiline_labels) 
                    if offset_to_linecol(src, l.start)[0] == ln]
        ending = [i for i,l in enumerate(multiline_labels)
                  if offset_to_linecol(src, l.end)[0] == ln]
        ongoing = [i for i,l in enumerate(multiline_labels)
                   if offset_to_linecol(src, l.start)[0] < ln < offset_to_linecol(src, l.end)[0]]

        # Build the source line content with prefix characters for each label level
        prefix_chars = []
        if ln == all_line_nums[0]:
            # First source line
            for i in range(nml):
                if i in starting:
                    # ╭──▶ 
                    arrows = '─' * max(0, nml - i - 1)
                    prefix_chars = [C(PURPLE, '╭' + '─' * (nml-1-i) + '▶ ')]
                    break

        # Simpler approach: render based on position in label list
        src_content = ''
        if starting:
            idx = starting[0]
            depth = nml - 1 - idx  # nesting depth
            arrow_prefix = ''
            for j in range(nml):
                if j < idx:
                    arrow_prefix += C(PURPLE, '│ ')
                elif j == idx:
                    arrow_prefix += C(PURPLE, '╭' + '─' * (nml - 1 - idx) + '▶ ')
                    break
            src_content = arrow_prefix + src_line
        elif ending:
            idx = ending[0]
            arrow_prefix = ''
            for j in range(nml):
                if j < idx:
                    arrow_prefix += C(PURPLE, '│ ')
                elif j == idx:
                    arrow_prefix += C(PURPLE, '├' + '─' * (nml - 1 - idx) + '▶ ')
                    break
            src_content = arrow_prefix + src_line
        else:
            # Ongoing
            arrow_prefix = ''.join(C(PURPLE, '│ ') for _ in range(nml))
            src_content = arrow_prefix

        lines.append(f" {C(GRAY, num_str + ' │')} {C(PURPLE, src_content)}")

    # Now render the annotations (label messages)
    # For each label from innermost to outermost
    for idx in range(nml - 1, -1, -1):
        lbl = multiline_labels[idx]
        # Show the annotation line with appropriate prefix
        prefix_str = ''
        for j in range(nml):
            if j < idx:
                prefix_str += C(PURPLE, '│ ')
            elif j == idx:
                pass

        end_ln, end_col = offset_to_linecol(src, lbl.end)

        # Continuation line  
        cont_prefix = ''.join(C(PURPLE, '│ ') for j in range(idx))
        inner_prefix = ''.join(C(PURPLE, '│ ') for j in range(idx+1, nml)) if idx < nml-1 else ''
        tail = ' ' * (13 + 2*(nml-1-idx))  # approximate
        lines.append(f"{dot_prefix} {cont_prefix}{C(PURPLE,'│')}{tail}")

