        if t.t==TT.REC: self.adv(); return self.attrset_expr(True) if self.at(TT.LBRACE) else NNull(t.s,t.e)
        if t.t==TT.LET: return self.let_expr()
        if t.t==TT.IF: return self.if_expr()
        if t.t==TT.WITH: return self.with_expr()
        if t.t==TT.ASSERT: return self.assert_expr()
        self.errs.append(ParseError(f"Unexpected '{t.v}'",t.s,t.e))
