    __slots__=('start','end','v')
    def __init__(self,s,e,v): super().__init__(s,e); self.v=v
class NStr(N):
    __slots__=('start','end')
class NPath(N):
    __slots__=('start','end','v')
    def __init__(self,s,e,v): super().__init__(s,e); self.v=v
class NUri(N):
    __slots__=('start','end','v')
    def __init__(self,s,e,v): super().__init__(s,e); self.v=v
class NBool(N):
    __slots__=('start','end','v')
    def __init__(self,s,e,v): super().__init__(s,e); self.v=v
class NNull(N):
