class Parser:
    def __init__(self,toks): self.T=toks; self.p=0; self.errs=[]
    def cur(self): return self.T[min(self.p,len(self.T)-1)]
    def pk(self,n=1): return self.T[min(self.p+n,len(self.T)-1)]
    def at(self,*tt): return self.cur().t in tt
    def adv(self):
        t=self.T[self.p]
        if self.p<len(self.T)-1: self.p+=1
