        return NAssert(t.s,body.end,c,body)

def parse_nix(src):
    toks=lex(src); p=Parser(toks); tree=p.parse(); return tree,p.errs

# Position utilities
def offset_to_lc(src, offset):
    """Return (1-based line, 1-based col) for byte offset."""
    line=1; col=1
    for i,c in enumerate(src):
        if i==offset: return (line,col)
        if c=='\n': line+=1; col=1
        else: col+=1
    return (line,col)

def line_start(src, line):
    """Byte offset of start of 1-based line."""
    pos=0; ln=1
    while ln<line:
        i=src.find('\n',pos)
        if i<0: return len(src)
        pos=i+1; ln+=1
    return pos

def get_line(src, line):
    ls=line_start(src,line)
    le=src.find('\n',ls)
    return src[ls:le if le>=0 else len(src)]

def line_count(src): return src.count('\n')+1

# Rendering
def render_msg(msg):
    """Render message with backtick items in cyan."""
    parts=re.split(r'(`[^`]*`)',msg); out=[]
    for p in parts:
        if p.startswith('`') and p.endswith('`'): out.append(Cy(p[1:-1]))
        else: out.append(p)
    return ''.join(out)

def render_source_line(src_line, span_s, span_e):
    """Render source line with purple for span, lgray for rest."""
    out=[]
    for i,c in enumerate(src_line):
        if span_s<=i<span_e: out.append(Pu(c))
        else: out.append(LG(c))
    return ''.join(out)

def render_single_diag(code, sev, title, src, filename, labels):
    """
    labels = list of (start_offset, end_offset, message, is_primary)
    """
    out=[]
    if sev=='W': hdr=Ye(f"[W{code:02d}] Warning:")+f" {title}"
    else: hdr=Re(f"[E{code:02d}] Error:")+f" {title}"
    out.append(hdr)

    if not labels:
        return '\n'.join(out)

    # Calculate gutter width from all label lines
    all_lns=[offset_to_lc(src,l[0])[0] for l in labels]+[offset_to_lc(src,l[1])[0] for l in labels if l[1]<=len(src)]
    max_ln=max(all_lns) if all_lns else 1
    nw=len(str(max_ln))  # number width
    ps=nw+2  # prefix spaces for header/footer lines

    # Location header
    first=labels[0]
    fl,fc=offset_to_lc(src,first[0])
    out.append(f"{' '*ps}{G('╭─[')}{filename}:{fl}:{fc}{G(']')}")
    out.append(f"{' '*ps}{G('│')}")

    # Check if any label spans multiple lines
    multiline=[l for l in labels if offset_to_lc(src,l[0])[0]!=offset_to_lc(src,l[1])[0]]
    singleline=[l for l in labels if offset_to_lc(src,l[0])[0]==offset_to_lc(src,l[1])[0]]

    dp=f" {G(' '*nw+' ·')}"  # dot prefix for annotation lines

    if not multiline:
        # All single-line labels
        for lbl in labels:
            ls,le,msg,_=lbl
            ln,lc=offset_to_lc(src,ls)
            en,ec=offset_to_lc(src,le)
            src_line=get_line(src,ln)
            lso=line_start(src,ln)
            ss=ls-lso; se=le-lso
            # Clamp
            se=min(se,len(src_line))
            ss=max(0,min(ss,len(src_line)))
            num_str=str(ln).rjust(nw)
            out.append(f" {G(num_str+' │')} {render_source_line(src_line,ss,se)}")
            # Underline
            length=max(1,se-ss)
            center=length//2
            ul=' '*ss+''.join(Pu('┬' if i==center else '─') for i in range(length))+'  '
            out.append(f"{dp} {ul}")
            # Annotation
            arrow_pos=ss+center
            ann=' '*arrow_pos+Pu('╰')+Pu('─'*(max(1,length-center-1)))+' '+render_msg(msg)
            out.append(f"{dp} {ann}")
    else:
        # Multi-line labels - use box drawing
        out.extend(_render_multiline(src, labels, nw, ps, dp))

    out.append(G('─'*(nw+2)+'╯'))
    return '\n'.join(out)

def _render_multiline(src, labels, nw, ps, dp):
    """Render diagnostics with multi-line spans."""
    out=[]
    # Collect unique line numbers to show
    line_set=set()
    for l in labels:
        sl=offset_to_lc(src,l[0])[0]
        el=offset_to_lc(src,l[1])[0]
        line_set.add(sl)
        if sl!=el: line_set.add(el)
    sorted_lines=sorted(line_set)

    # Separate multi-line from single-line labels
    ml=[l for l in labels if offset_to_lc(src,l[0])[0]!=offset_to_lc(src,l[1])[0]]
    sl_=[l for l in labels if offset_to_lc(src,l[0])[0]==offset_to_lc(src,l[1])[0]]

    nml=len(ml)

    if nml==0:
        # All single-line at different lines
        for lbl in labels:
            ls,le,msg,_=lbl
            ln,_=offset_to_lc(src,ls)
            src_line=get_line(src,ln)
            lso=line_start(src,ln)
            ss=ls-lso; se=le-lso
            se=min(se,len(src_line)); ss=max(0,min(ss,len(src_line)))
            num_str=str(ln).rjust(nw)
            out.append(f" {G(num_str+' │')} {render_source_line(src_line,ss,se)}")
            length=max(1,se-ss); center=length//2
            ul=' '*ss+''.join(Pu('┬' if i==center else '─') for i in range(length))+'  '
            out.append(f"{dp} {ul}")
            ann=' '*(ss+center)+Pu('╰')+Pu('─'*max(1,length-center-1))+' '+render_msg(msg)
            out.append(f"{dp} {ann}")
        return out

    # For each source line, render with appropriate box-drawing prefix
    for ln in sorted_lines:
        src_line=get_line(src,ln)
        num_str=str(ln).rjust(nw)
        # Determine which multi-line labels start/end here
        starting=[i for i,l in enumerate(ml) if offset_to_lc(src,l[0])[0]==ln]
        ending=[i for i,l in enumerate(ml) if offset_to_lc(src,l[1])[0]==ln]
        ongoing=[i for i,l in enumerate(ml) if offset_to_lc(src,l[0])[0]<ln<offset_to_lc(src,l[1])[0]]

        prefix=''
        if starting:
            idx=starting[0]
            for j in range(idx): prefix+=Pu('│ ')
            n_dashes=nml-1-idx
            prefix+=Pu('╭'+'─'*n_dashes+'▶ ')
        elif ending:
            idx=ending[0]
            for j in range(idx): prefix+=Pu('│ ')
            n_dashes=nml-1-idx
            prefix+=Pu('├'+'─'*n_dashes+'▶ ')
        else:
            for j in range(nml): prefix+=Pu('│ ')

        # Content after prefix is the raw source line in purple
        content=''.join(Pu(c) for c in src_line)
        out.append(f" {G(num_str+' │')} {prefix}{content}")

    # Annotations for each multi-line label, innermost first
    for idx in range(nml-1,-1,-1):
        lbl=ml[idx]
        _,_,msg,_=lbl
        # Continuation line
        cont=''.join(Pu('│ ') for j in range(idx))
        inner_bars=''.join(Pu('│ ') for j in range(idx+1,nml)) if nml>idx+1 else ''
        # How many spaces for the message alignment?
        n_tail=2*(nml-1-idx)+13
        out.append(f"{dp} {cont}{Pu('│')}{' '*n_tail}{inner_bars}")
        # Annotation line
        n_dashes=2*(nml-1-idx)+13
        out.append(f"{dp} {cont}{Pu('╰'+'─'*n_dashes+' ')}{render_msg(msg)}")

    return out

