        t=self.adv(); s=t.s
        if self.at(LBRACE):
            self.adv(); binds=[]
            while not self.at(RBRACE,EOF):
                b=self.binding()
                if b: binds.append(b)
            et=self.cur()
            if self.at(RBRACE): self.adv()
            return NLegacyLet(s,et.e,binds)
        binds=[]
        while not self.at(T_IN,EOF):
            b=self.binding()
            if b: binds.append(b)
        if self.at(T_IN): self.adv()
        body=self.expr()
        return NLet(s,body.end,binds,body)
    def if_x(self):
        t=self.adv(); c=self.expr()
        if self.at(T_THEN): self.adv()
        th=self.expr()
        if self.at(T_ELSE): self.adv()
        el=self.expr()
