                pos+=1
                while pos<n and src[pos] not in ' \t\n\r;,)}\]"\'`#': pos+=1
                R.append(Tok(URI,src[s:pos],s,pos))
            else: R.append(Tok(tt,w,s,pos))
            continue
        if c=='"':
            pos+=1
            while pos<n:
                ch=src[pos]
                if ch=='"': pos+=1; break
                elif ch=='\\': pos+=2
                elif ch=='$' and pos+1<n and src[pos+1]=='{':
                    pos+=2; depth=1
                    while pos<n and depth>0:
                        if src[pos]=='{': depth+=1
                        elif src[pos]=='}': depth-=1
                        elif src[pos]=='"' and depth>0:
                            pos+=1
                            while pos<n and src[pos]!='"':
                                if src[pos]=='\\': pos+=1
                                pos+=1
                        if depth>0: pos+=1
                        else: pos+=1; break
                else: pos+=1
            R.append(Tok(STRING,src[s:pos],s,pos)); continue
        if c=="'" and pos+1<n and src[pos+1]=="'":
            pos+=2
            while pos<n:
                if src[pos]=="'" and pos+1<n and src[pos+1]=="'":
                    if pos+2<n and src[pos+2]=="'": pos+=3; continue
                    pos+=2; break
                elif src[pos]=='$' and pos+1<n and src[pos+1]=='{':
                    pos+=2; depth=1
                    while pos<n and depth>0:
                        if src[pos]=='{': depth+=1
                        elif src[pos]=='}': depth-=1
                        pos+=1
                else: pos+=1
            R.append(Tok(MSTRING,src[s:pos],s,pos)); continue
        if (c=='/' and pos+1<n and (src[pos+1].isalpha() or src[pos+1] in '_./')) or \
           (c=='.' and pos+1<n and src[pos+1]=='/'):
            pos+=1
            while pos<n and src[pos] not in ' \t\n\r;,)}\]"\'`#': pos+=1
            R.append(Tok(PATH,src[s:pos],s,pos)); continue
        if c=='~' and pos+1<n and src[pos+1]=='/':
            pos+=2
            while pos<n and src[pos] not in ' \t\n\r;,)}\]"\'`#': pos+=1
            R.append(Tok(HPATH,src[s:pos],s,pos)); continue
        if c=='<':
            j=pos+1; ok=True
            while j<n and src[j]!='>':
                if src[j] in ' \t\n': ok=False; break
                j+=1
            if ok and j<n and src[j]=='>' and j>pos+1:
                R.append(Tok(SPATH,src[pos:j+1],pos,j+1)); pos=j+1; continue
            elif pos+1<n and src[pos+1]=='=': R.append(Tok(LEQ,'<=',pos,pos+2)); pos+=2
            else: R.append(Tok(LT,'<',pos,pos+1)); pos+=1
            continue
        if c=='+' and pos+1<n and src[pos+1]=='+': R.append(Tok(CONCAT,'++',pos,pos+2)); pos+=2; continue
        if c=='+': R.append(Tok(PLUS,'+',pos,pos+1)); pos+=1; continue
        if c=='-' and pos+1<n and src[pos+1]=='>': R.append(Tok(IMPL,'->',pos,pos+2)); pos+=2; continue
        if c=='-': R.append(Tok(MINUS,'-',pos,pos+1)); pos+=1; continue
        if c=='*': R.append(Tok(STAR,'*',pos,pos+1)); pos+=1; continue
        if c=='/' and pos+1<n and src[pos+1]=='/': R.append(Tok(UPDATE,'//',pos,pos+2)); pos+=2; continue
        if c=='/': R.append(Tok(SLASH,'/',pos,pos+1)); pos+=1; continue
        if c=='=' and pos+1<n and src[pos+1]=='=': R.append(Tok(EQ,'==',pos,pos+2)); pos+=2; continue
        if c=='=': R.append(Tok(ASSIGN,'=',pos,pos+1)); pos+=1; continue
        if c=='!' and pos+1<n and src[pos+1]=='=': R.append(Tok(NEQ,'!=',pos,pos+2)); pos+=2; continue
        if c=='!': R.append(Tok(NOT,'!',pos,pos+1)); pos+=1; continue
        if c=='>' and pos+1<n and src[pos+1]=='=': R.append(Tok(GEQ,'>=',pos,pos+2)); pos+=2; continue
        if c=='>': R.append(Tok(GT,'>',pos,pos+1)); pos+=1; continue
        if c=='&' and pos+1<n and src[pos+1]=='&': R.append(Tok(AND,'&&',pos,pos+2)); pos+=2; continue
        if c=='&': R.append(Tok(ERR,'&',pos,pos+1)); pos+=1; continue
        if c=='|' and pos+1<n and src[pos+1]=='|': R.append(Tok(OR,'||',pos,pos+2)); pos+=2; continue
        if c=='|': R.append(Tok(ERR,'|',pos,pos+1)); pos+=1; continue
        if c=='.' and pos+2<n and src[pos+1]=='.' and src[pos+2]=='.': R.append(Tok(ELLIPSIS,'...',pos,pos+3)); pos+=3; continue
        if c=='.': R.append(Tok(DOT,'.',pos,pos+1)); pos+=1; continue
        SM={'(':LPAREN,')':RPAREN,'{':LBRACE,'}':RBRACE,'[':LBRACKET,']':RBRACKET,
            ':':COLON,';':SEMICOLON,'?':QUESTION,'@':AT,',':COMMA}
        if c in SM: R.append(Tok(SM[c],c,pos,pos+1)); pos+=1; continue
        R.append(Tok(ERR,c,pos,pos+1)); pos+=1
    R.append(Tok(EOF,'',n,n)); return R

# AST nodes
class N:
    __slots__=('start','end')
    def __init__(self,s,e): self.start=s; self.end=e

class NInt(N):
    __slots__=('start','end','v')
    def __init__(self,s,e,v): super().__init__(s,e); self.v=v
class NFloat(N):
    __slots__=('start','end','v')
    def __init__(self,s,e,v): super().__init__(s,e); self.v=v
class NStr(N):
    __slots__=('start','end')
class NPath(N):
    __slots__=('start','end','v')
    def __init__(self,s,e,v): super().__init__(s,e); self.v=v
class NUri(N):
    __slots__=('start','end','v')
    def __init__(self,s,e,v): super().__init__(s,e); self.v=v
class NBool(N):
    __slots__=('start','end','v')
    def __init__(self,s,e,v): super().__init__(s,e); self.v=v
class NNull(N):
    __slots__=('start','end')
class NIdent(N):
    __slots__=('start','end','name')
    def __init__(self,s,e,name): super().__init__(s,e); self.name=name
class NSelect(N):
    __slots__=('start','end','obj','attr','dflt')
    def __init__(self,s,e,obj,attr,dflt=None): super().__init__(s,e); self.obj=obj; self.attr=attr; self.dflt=dflt
class NHasAttr(N):
    __slots__=('start','end','obj','path')
    def __init__(self,s,e,obj,path): super().__init__(s,e); self.obj=obj; self.path=path
class NList(N):
    __slots__=('start','end','items')
    def __init__(self,s,e,items): super().__init__(s,e); self.items=items
class NAttrSet(N):
    __slots__=('start','end','rec','bindings')
    def __init__(self,s,e,rec,bindings): super().__init__(s,e); self.rec=rec; self.bindings=bindings
class NLambda(N):
    __slots__=('start','end','arg','body')
    def __init__(self,s,e,arg,body): super().__init__(s,e); self.arg=arg; self.body=body
class NApply(N):
    __slots__=('start','end','f','a')
    def __init__(self,s,e,f,a): super().__init__(s,e); self.f=f; self.a=a
class NIf(N):
    __slots__=('start','end','c','t','el')
    def __init__(self,s,e,c,t,el): super().__init__(s,e); self.c=c; self.t=t; self.el=el
class NWith(N):
    __slots__=('start','end','env','body')
    def __init__(self,s,e,env,body): super().__init__(s,e); self.env=env; self.body=body
class NLet(N):
    __slots__=('start','end','binds','body')
    def __init__(self,s,e,binds,body): super().__init__(s,e); self.binds=binds; self.body=body
class NLegacyLet(N):
    __slots__=('start','end','binds')
    def __init__(self,s,e,binds): super().__init__(s,e); self.binds=binds
class NAssert(N):
    __slots__=('start','end','c','body')
    def __init__(self,s,e,c,body): super().__init__(s,e); self.c=c; self.body=body
class NBinOp(N):
    __slots__=('start','end','op','l','r')
    def __init__(self,s,e,op,l,r): super().__init__(s,e); self.op=op; self.l=l; self.r=r
class NUnary(N):
    __slots__=('start','end','op','x')
    def __init__(self,s,e,op,x): super().__init__(s,e); self.op=op; self.x=x
class NParen(N):
    __slots__=('start','end','x')
    def __init__(self,s,e,x): super().__init__(s,e); self.x=x
class NBinding(N):
    __slots__=('start','end','path','value')
    def __init__(self,s,e,path,value): super().__init__(s,e); self.path=path; self.value=value
class NInherit(N):
    __slots__=('start','end','frm','attrs')
    def __init__(self,s,e,frm,attrs): super().__init__(s,e); self.frm=frm; self.attrs=attrs
class NPattern(N):
    __slots__=('start','end','formals','ellipsis','bind')
    def __init__(self,s,e,formals,ellipsis,bind): super().__init__(s,e); self.formals=formals; self.ellipsis=ellipsis; self.bind=bind
class NFormal(N):
    __slots__=('start','end','name','dflt')
    def __init__(self,s,e,name,dflt): super().__init__(s,e); self.name=name; self.dflt=dflt

class ParseError(Exception):
    def __init__(self,msg,s,e=None): super().__init__(msg); self.s=s; self.e=e or s

class Parser:
    def __init__(self,toks): self.T=toks; self.p=0; self.errs=[]
    def cur(self): return self.T[min(self.p,len(self.T)-1)]
    def pk(self,n=1): return self.T[min(self.p+n,len(self.T)-1)]
    def at(self,*tt): return self.cur().t in tt
    def adv(self):
        t=self.T[self.p]
        if self.p<len(self.T)-1: self.p+=1
        return t
    def eat(self,tt):
        t=self.cur()
        if t.t!=tt: self.errs.append(ParseError(f"Expected {tt}",t.s,t.e))
        else: self.adv()
        return t
    def parse(self): return self.expr()
    def expr(self): return self.lam()
    def lam(self):
        sp=self.p
        if self.at(IDENT) and self.pk(1).t==COLON:
            t=self.adv(); self.adv(); body=self.lam()
            return NLambda(t.s,body.end,NIdent(t.s,t.e,t.v),body)
        if self.at(IDENT) and self.pk(1).t==AT and self.pk(2).t==LBRACE:
            t=self.adv(); self.adv(); pat=self.pattern()
            pat.bind=NIdent(t.s,t.e,t.v); self.eat(COLON); body=self.lam()
            return NLambda(t.s,body.end,pat,body)
        if self.at(LBRACE) and self._ispat():
            s0=self.cur().s; pat=self.pattern()
            if self.at(AT):
                self.adv(); bt=self.cur(); self.eat(IDENT); pat.bind=NIdent(bt.s,bt.e,bt.v)
            if self.at(COLON):
                self.adv(); body=self.lam()
                return NLambda(s0,body.end,pat,body)
            self.p=sp
        return self.impl()
    def _ispat(self):
        i=self.p+1; toks=self.T; n=len(toks)
        depth=1; j=i
        while j<n and depth>0:
            if toks[j].t==LBRACE: depth+=1
            elif toks[j].t==RBRACE: depth-=1
            j+=1
        if j<n and toks[j].t in (COLON,AT): return True
        if i<n and toks[i].t in (ELLIPSIS,RBRACE): return False
        if i<n and toks[i].t==IDENT:
            if i+1<n and toks[i+1].t in (COMMA,QUESTION,RBRACE): return True
        return j<n and toks[j].t in (COLON,AT)
    def pattern(self):
        st=self.adv().s; formals=[]; ellipsis=False
        while not self.at(RBRACE,EOF):
            if self.at(ELLIPSIS): self.adv(); ellipsis=True; break
            if self.at(IDENT):
                nt=self.adv(); dflt=None
                if self.at(QUESTION): self.adv(); dflt=self.expr()
                formals.append(NFormal(nt.s,nt.e,nt.v,dflt))
            if self.at(COMMA): self.adv()
            elif not self.at(RBRACE,ELLIPSIS,EOF): break
        et=self.cur()
        if self.at(RBRACE): self.adv()
        return NPattern(st,et.e,formals,ellipsis,None)
    def impl(self):
        l=self.orr()
        if self.at(IMPL): self.adv(); r=self.impl(); return NBinOp(l.start,r.end,'->',l,r)
        return l
    def orr(self):
        l=self.andd()
        while self.at(OR): self.adv(); r=self.andd(); l=NBinOp(l.start,r.end,'||',l,r)
        return l
    def andd(self):
        l=self.nott()
        while self.at(AND): self.adv(); r=self.nott(); l=NBinOp(l.start,r.end,'&&',l,r)
        return l
    def nott(self):
        if self.at(NOT): t=self.adv(); x=self.nott(); return NUnary(t.s,x.end,'!',x)
        return self.eq()
    def eq(self):
        l=self.cmp()
        if self.at(EQ,NEQ): op=self.adv(); r=self.cmp(); return NBinOp(l.start,r.end,op.v,l,r)
        return l
    def cmp(self):
        l=self.upd()
        if self.at(LT,GT,LEQ,GEQ): op=self.adv(); r=self.upd(); return NBinOp(l.start,r.end,op.v,l,r)
        return l
    def upd(self):
        l=self.cat()
        while self.at(UPDATE): self.adv(); r=self.cat(); l=NBinOp(l.start,r.end,'//',l,r)
        return l
    def cat(self):
        l=self.add()
        while self.at(CONCAT): self.adv(); r=self.add(); l=NBinOp(l.start,r.end,'++',l,r)
        return l
    def add(self):
        l=self.mul()
        while self.at(PLUS,MINUS): op=self.adv(); r=self.mul(); l=NBinOp(l.start,r.end,op.v,l,r)
        return l
    def mul(self):
        l=self.neg()
        while self.at(STAR,SLASH): op=self.adv(); r=self.neg(); l=NBinOp(l.start,r.end,op.v,l,r)
        return l
    def neg(self):
        if self.at(MINUS): t=self.adv(); x=self.neg(); return NUnary(t.s,x.end,'-',x)
        return self.hasattr()
    def hasattr(self):
        l=self.app()
        while self.at(QUESTION):
            self.adv(); path=self.attrpath()
            end=path[-1].end if path else l.end
            l=NHasAttr(l.start,end,l,path)
        return l
    def app(self):
        f=self.sel()
        while self._exprstart(): a=self.sel(); f=NApply(f.start,a.end,f,a)
        return f
    def _exprstart(self):
        t=self.cur().t
        if t in (IDENT,INT,FLOAT,STRING,MSTRING,PATH,HPATH,SPATH,URI,T_NULL,T_TRUE,T_FALSE,LPAREN,LBRACKET,T_REC): return True
        if t==LBRACE: return not self._ispat()
        if t in (T_LET,T_IF,T_WITH,T_ASSERT): return True
        return False
    def sel(self):
        x=self.primary()
        while self.at(DOT):
            self.adv(); a=self._selattr()
            if self.at(T_OR_KW): self.adv(); d=self.sel(); return NSelect(x.start,d.end,x,a,d)
            x=NSelect(x.start,a.end,x,a)
        return x
    def _selattr(self):
        t=self.cur()
        if t.t in (IDENT,T_OR_KW): self.adv(); return NIdent(t.s,t.e,t.v)
        elif t.t in (STRING,MSTRING): self.adv(); return NStr(t.s,t.e)
        if not self.at(EOF): self.adv()
        return NIdent(t.s,t.e,t.v)
    def primary(self):
        t=self.cur()
        if t.t==INT: self.adv(); return NInt(t.s,t.e,t.v)
        if t.t==FLOAT: self.adv(); return NFloat(t.s,t.e,t.v)
        if t.t==T_TRUE: self.adv(); return NBool(t.s,t.e,True)
        if t.t==T_FALSE: self.adv(); return NBool(t.s,t.e,False)
        if t.t==T_NULL: self.adv(); return NNull(t.s,t.e)
        if t.t in (STRING,MSTRING): self.adv(); return NStr(t.s,t.e)
        if t.t in (PATH,HPATH,SPATH): self.adv(); return NPath(t.s,t.e,t.v)
        if t.t==URI: self.adv(); return NUri(t.s,t.e,t.v)
        if t.t==IDENT: self.adv(); return NIdent(t.s,t.e,t.v)
        if t.t==LPAREN:
            s=t.s; self.adv(); x=self.expr(); et=self.cur()
            if self.at(RPAREN): self.adv(); end=et.e
            else: end=x.end; self.errs.append(ParseError("Expected ')'",et.s))
            return NParen(s,end,x)
        if t.t==LBRACKET:
            s=t.s; self.adv(); items=[]
            while not self.at(RBRACKET,EOF): items.append(self.sel())
            et=self.cur()
            if self.at(RBRACKET): self.adv()
            return NList(s,et.e,items)
        if t.t==LBRACE: return self.attrset_x(False)
        if t.t==T_REC: self.adv(); return self.attrset_x(True) if self.at(LBRACE) else NNull(t.s,t.e)
        if t.t==T_LET: return self.let_x()
        if t.t==T_IF: return self.if_x()
        if t.t==T_WITH: return self.with_x()
        if t.t==T_ASSERT: return self.assert_x()
        self.errs.append(ParseError(f"Unexpected '{t.v}'",t.s,t.e))
        if not self.at(EOF): self.adv()
        return NNull(t.s,t.e)
    def attrset_x(self,rec):
        s=self.cur().s; self.adv(); binds=[]
        while not self.at(RBRACE,EOF):
            b=self.binding()
            if b: binds.append(b)
        et=self.cur()
        if self.at(RBRACE): self.adv()
        return NAttrSet(s,et.e,rec,binds)
    def binding(self):
        t=self.cur()
        if t.t==T_INHERIT: return self.inherit_x()
        if t.t in (IDENT,T_OR_KW,STRING,MSTRING):
            path=self.attrpath()
            if self.at(ASSIGN):
                self.adv(); val=self.expr(); et=self.cur()
                end=et.e if self.at(SEMICOLON) else val.end
                if self.at(SEMICOLON): self.adv()
                return NBinding(path[0].start if path else t.s,end,path,val)
        if not self.at(RBRACE,EOF):
            self.errs.append(ParseError(f"Unexpected '{t.v}'",t.s))
            self.adv()
        return None
    def inherit_x(self):
        t=self.adv(); frm=None
        if self.at(LPAREN): self.adv(); frm=self.expr(); self.at(RPAREN) and self.adv()
        attrs=[]
        while self.at(IDENT,T_OR_KW): at=self.adv(); attrs.append(NIdent(at.s,at.e,at.v))
        et=self.cur(); end=et.e if self.at(SEMICOLON) else (attrs[-1].end if attrs else t.e)
        if self.at(SEMICOLON): self.adv()
        return NInherit(t.s,end,frm,attrs)
    def attrpath(self):
        attrs=[]
        def one():
            t=self.cur()
            if t.t in (IDENT,T_OR_KW): self.adv(); return NIdent(t.s,t.e,t.v)
            elif t.t in (STRING,MSTRING): self.adv(); return NStr(t.s,t.e)
            return None
        a=one()
        if a: attrs.append(a)
        while self.at(DOT): self.adv(); a=one();
        if a and attrs: attrs.append(a)
        elif a: attrs.append(a)
        return attrs
    def let_x(self):
        t=self.adv(); s=t.s
        if self.at(LBRACE):
            self.adv(); binds=[]
            while not self.at(RBRACE,EOF):
                b=self.binding()
                if b: binds.append(b)
            et=self.cur()
            if self.at(RBRACE): self.adv()
            return NLegacyLet(s,et.e,binds)
        binds=[]
        while not self.at(T_IN,EOF):
            b=self.binding()
            if b: binds.append(b)
        if self.at(T_IN): self.adv()
        body=self.expr()
        return NLet(s,body.end,binds,body)
    def if_x(self):
        t=self.adv(); c=self.expr()
        if self.at(T_THEN): self.adv()
        th=self.expr()
        if self.at(T_ELSE): self.adv()
        el=self.expr()
        return NIf(t.s,el.end,c,th,el)
    def with_x(self):
        t=self.adv(); env=self.expr()
        if self.at(SEMICOLON): self.adv()
        body=self.expr()
        return NWith(t.s,body.end,env,body)
    def assert_x(self):
        t=self.adv(); c=self.expr()
        if self.at(SEMICOLON): self.adv()
        body=self.expr()
        return NAssert(t.s,body.end,c,body)

def parse_nix(src):
    toks=lex(src); p=Parser(toks); tree=p.parse(); return tree,p.errs

# Position utilities
def offset_to_lc(src, offset):
    """Return (1-based line, 1-based col) for byte offset."""
    line=1; col=1
    for i,c in enumerate(src):
        if i==offset: return (line,col)
        if c=='\n': line+=1; col=1
        else: col+=1
    return (line,col)

def line_start(src, line):
    """Byte offset of start of 1-based line."""
    pos=0; ln=1
    while ln<line:
        i=src.find('\n',pos)
        if i<0: return len(src)
        pos=i+1; ln+=1
    return pos

def get_line(src, line):
    ls=line_start(src,line)
    le=src.find('\n',ls)
    return src[ls:le if le>=0 else len(src)]

def line_count(src): return src.count('\n')+1

# Rendering
def render_msg(msg):
    """Render message with backtick items in cyan."""
    parts=re.split(r'(`[^`]*`)',msg); out=[]
    for p in parts:
        if p.startswith('`') and p.endswith('`'): out.append(Cy(p[1:-1]))
        else: out.append(p)
    return ''.join(out)

def render_source_line(src_line, span_s, span_e):
    """Render source line with purple for span, lgray for rest."""
    out=[]
    for i,c in enumerate(src_line):
        if span_s<=i<span_e: out.append(Pu(c))
        else: out.append(LG(c))
    return ''.join(out)

def render_single_diag(code, sev, title, src, filename, labels):
    """
    labels = list of (start_offset, end_offset, message, is_primary)
    """
    out=[]
    if sev=='W': hdr=Ye(f"[W{code:02d}] Warning:")+f" {title}"
    else: hdr=Re(f"[E{code:02d}] Error:")+f" {title}"
    out.append(hdr)

    if not labels:
        return '\n'.join(out)

    # Calculate gutter width from all label lines
